import React, { useMemo, useState, useEffect } from "react";


const starterRecipes = [
  {
    id: "r1", title: "Creamy Tuscan Pasta", category: "Dinner", time: 30, difficulty: "Easy", servings: 2,
    story: "Legend has it that this pasta began in a tiny kitchen in Tuscany, where a home cook was trying to turn a handful of tomatoes, spinach, and leftover cream into dinner for unexpected guests. The dish became a family favorite, eventually making its way onto neighborhood tables. Flavorlyst's version keeps that same cozy, make-it-tonight spirit.", author: "Kitchen Collective",
    image: "https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=1200&q=85",
    description: "Silky pasta with garlic, spinach, tomatoes, and Parmesan.",
    tags: ["pasta", "quick", "vegetarian"],
    ingredients: [{q: 8,u:"oz",n:"pasta"},{q:1,u:"tbsp",n:"olive oil"},{q:2,u:"clove",n:"garlic"},{q:1,u:"cup",n:"cherry tomatoes"},{q:2,u:"cup",n:"spinach"},{q:0.5,u:"cup",n:"heavy cream"},{q:0.5,u:"cup",n:"Parmesan"}],
    steps: ["Bring a large pot of water to a boil. Salt the water generously, add the pasta, and cook according to the package directions until just tender (usually 8–12 minutes). Before draining, save about 1 cup of pasta water.","While the pasta cooks, warm the olive oil in a large skillet over medium heat. Add the minced garlic and cook for 30–60 seconds, stirring constantly so it smells fragrant but does not brown.","Add the cherry tomatoes and cook for 4–6 minutes, stirring occasionally, until they soften and some begin to burst. Add the spinach and stir for 1–2 minutes until wilted.","Lower the heat to medium-low. Stir in the heavy cream and simmer gently for 2–3 minutes; do not let it boil hard. Season with salt and black pepper to taste.","Add the drained pasta and grated Parmesan. Toss for 1–2 minutes, adding reserved pasta water a splash at a time until the sauce coats the noodles. Taste, adjust seasoning, and serve hot."]
  },
  {
    id: "r2", title: "Crispy Honey Chicken", category: "Dinner", time: 35, difficulty: "Medium", servings: 4,
    story: "This recipe was inspired by the kind of weeknight dinner that disappears from the table before anyone remembers to take a photo. Mia's Kitchen imagined a simple honey glaze that could turn golden chicken into something special without making dinner complicated. The sweet-and-tangy sauce became the signature.", author: "Mia's Kitchen",
    image: "https://cdn.emmasrezepte.de/images/7759f88f-8cf7-4fb6-9af8-1404c00c07c7_U3_b2988d31.webp",
    description: "Golden chicken glazed with a sweet, tangy honey sauce.",
    tags: ["chicken", "family", "high-protein"],
    ingredients: [{q:1.5,u:"lb",n:"chicken breast"},{q:0.5,u:"cup",n:"flour"},{q:2,u:"tbsp",n:"olive oil"},{q:0.25,u:"cup",n:"honey"},{q:2,u:"tbsp",n:"soy sauce"},{q:1,u:"tbsp",n:"lemon juice"}],
    steps: ["Cut the chicken breast into even bite-size pieces so they cook at the same rate. Pat dry, then season lightly with salt and black pepper. Put the flour in a bowl and toss the chicken in it, shaking off the excess.","Heat the olive oil in a large skillet over medium heat. Add the chicken in one layer (cook in batches if crowded) and cook for about 3–5 minutes per side, turning until golden and the thickest pieces reach 165°F (74°C).","While the chicken cooks, whisk the honey, soy sauce, and lemon juice in a small bowl. Keep the sauce ready before adding it to the hot pan.","Reduce the heat to medium-low and return all chicken to the skillet. Pour in the sauce and stir for 1–3 minutes, scraping up browned bits, until the sauce bubbles gently and coats the chicken. If it thickens too much, add 1–2 teaspoons of water.","Check that the chicken reaches 165°F (74°C), then serve immediately with rice or vegetables if desired."]
  },
  {
    id: "r3", title: "Berry Breakfast Bowl", category: "Breakfast", time: 10, difficulty: "Easy", servings: 1,
    story: "The breakfast bowl has roots in the sunny idea that breakfast should feel like a fresh start. Fresh Start's original version was assembled from whatever berries and fruit were in season, with yogurt and granola added for crunch. It became a morning ritual because it takes only a few minutes but still feels like a little celebration.", author: "Fresh Start",
    image: "https://images.unsplash.com/photo-1623052935410-3fca63f73e10?auto=format&fit=crop&w=1200&q=85",
    description: "A bright yogurt bowl loaded with berries, banana, and crunchy toppings.",
    tags: ["breakfast", "fruit", "quick"],
    ingredients: [{q:1,u:"cup",n:"Greek yogurt"},{q:0.5,u:"cup",n:"berries"},{q:0.5,u:"",n:"banana"},{q:2,u:"tbsp",n:"granola"},{q:1,u:"tbsp",n:"honey"}],
    steps: ["Spoon the Greek yogurt into two serving bowls and smooth the tops with the back of a spoon.","Rinse the berries and pat them dry. Slice the banana into bite-size rounds, then arrange the fruit over the yogurt.","Scatter the granola over the fruit just before serving so it stays crunchy.","Drizzle with honey to taste. Serve immediately; no cooking is needed."]
  },
  {
    id: "r4", title: "Roasted Garlic Tomato Soup", category: "Lunch", time: 45, difficulty: "Easy", servings: 4,
    story: "On a chilly afternoon, the Home Table kitchen filled with the smell of tomatoes and garlic roasting in the oven. What started as an experiment to deepen the flavor of an ordinary tomato soup became a recipe people asked for again and again. The secret, according to the story, was giving the garlic and tomatoes enough time to caramelize.", author: "Home Table",
    image: "https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=1200&q=85",
    description: "Roasted tomatoes and garlic blended into a comforting soup.",
    tags: ["soup", "vegetarian", "comfort"],
    ingredients: [{q:2,u:"lb",n:"tomatoes"},{q:1,u:"head",n:"garlic"},{q:2,u:"tbsp",n:"olive oil"},{q:3,u:"cup",n:"vegetable broth"},{q:0.25,u:"cup",n:"cream"}],
    steps: ["Heat the oven to 425°F (220°C). Cut the tomatoes into halves or wedges and place them on a rimmed baking sheet with the garlic cloves. Drizzle with olive oil and season with salt and black pepper.","Roast for 25–30 minutes, turning the tomatoes once, until they are soft, browned at the edges, and juicy. Let the garlic cool enough to handle, then squeeze the softened cloves from their skins.","Transfer the roasted tomatoes, garlic, and pan juices to a blender with some of the warm vegetable broth. Blend until smooth, working in batches if needed and venting the lid carefully because hot liquid expands.","Pour into a saucepan, add the remaining broth, and simmer over medium-low heat for 8–10 minutes. Stir occasionally and add more broth if the soup is thicker than you like.","Lower the heat and stir in the cream. Warm for another 1–2 minutes without boiling, then taste and adjust salt and black pepper. Serve hot."]
  },
  {
    id: "r5", title: "Avocado Toast", category: "Breakfast", time: 8, difficulty: "Easy", servings: 1,
    story: "Everyday Eats traces this toast to slow weekend mornings, when there was just enough time to mash a ripe avocado and experiment with whatever was in the spice drawer. Lemon brought brightness, chili added a little spark, and a simple slice of toast became a breakfast staple.", author: "Everyday Eats",
    image: "https://images.unsplash.com/photo-1741732666754-392caf4bea63?auto=format&fit=crop&w=1200&q=85",
    description: "Creamy avocado on crisp toast with lemon and chili.",
    tags: ["breakfast", "quick"],
    ingredients: [{q:2,u:"slice",n:"bread"},{q:1,u:"",n:"avocado"},{q:1,u:"tsp",n:"lemon juice"},{q:1,u:"pinch",n:"chili flakes"}],
    steps: ["Toast the bread in a toaster or in a dry skillet over medium heat until crisp and golden to your liking.","Cut the avocado in half, remove the pit safely, and scoop the flesh into a bowl. Mash with the lemon juice and a pinch of salt until mostly smooth, leaving some chunks if you prefer.","Spread the avocado mixture evenly over the toast. Sprinkle with chili flakes and black pepper to taste.","Serve right away while the toast is still crisp. Add the chili flakes gradually if you prefer a milder flavor."]
  },
  {
    id: "r6", title: "Garden Greek Salad", category: "Lunch", time: 15, difficulty: "Easy", servings: 2,
    story: "The Green Spoon says this salad was born from a garden table in the middle of summer. Cucumbers, tomatoes, herbs, olives, and feta were gathered as they became ready, then tossed together with a quick lemon dressing. No complicated recipe was planned—the garden practically wrote it itself.", author: "The Green Spoon",
    image: "https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=1200&q=85",
    description: "Crisp vegetables, feta, olives, and a simple lemon dressing.",
    tags: ["salad", "vegetarian", "quick"],
    ingredients: [{q:2,u:"cup",n:"cucumber"},{q:2,u:"cup",n:"tomato"},{q:0.5,u:"cup",n:"feta"},{q:0.25,u:"cup",n:"olives"},{q:2,u:"tbsp",n:"olive oil"},{q:1,u:"tbsp",n:"lemon juice"}],
    steps: ["Rinse and dry the cucumber and tomatoes. Cut the cucumber into bite-size pieces, chop the tomatoes, and halve the olives. Put them in a large bowl.","In a small bowl, whisk the olive oil with the lemon juice, a pinch of dried oregano if available, and black pepper. Taste before adding salt because feta and olives are already salty.","Pour the dressing over the vegetables and olives, then toss gently until everything is lightly coated.","Crumble the feta over the top and fold it in gently so it keeps some texture. Taste, adjust lemon or pepper, and serve immediately."]
  },
  { id: "r7", title: "Blueberry Lemon Pancakes", category: "Breakfast", time: 20, difficulty: "Easy", servings: 2, story: "The story of Blueberry Lemon Pancakes started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://homesteadspoon.com/assets/images/1768874996392-7p5atynu.webp", description: "A bright, comforting recipe made for easy home cooking.", tags: ["breakfast","blueberry","flavorlyst"], ingredients: [{q:1.5,u:"cup",n:"flour"},{q:1,u:"cup",n:"milk"},{q:1,u:"large",n:"egg"},{q:1,u:"cup",n:"blueberries"},{q:1,u:"tbsp",n:"lemon juice"},{q:1,u:"tsp",n:"lemon zest"},{q:1,u:"tbsp",n:"butter"}], steps: ["In a large bowl, whisk the flour with a small pinch of salt if available. In a second bowl, whisk the milk, egg, lemon juice, and lemon zest until combined. Pour the wet mixture into the flour and stir just until no dry flour remains; a few small lumps are fine.","Gently fold the blueberries into the batter. Let the batter rest for 5 minutes while you heat the pan.","Warm a nonstick skillet or griddle over medium heat (about 350°F/175°C on an electric griddle). Lightly butter it. Pour about 1/4 cup batter per pancake, leaving space between pancakes.","Cook for 2–3 minutes, until bubbles appear on top and the edges look set. Flip carefully and cook another 1–2 minutes, until golden and the center is cooked through. Lower the heat if the outside browns before the middle cooks.","Serve warm with maple syrup or extra berries. Repeat with the remaining batter, lightly buttering the pan between batches."] },
  { id: "r8", title: "Classic French Toast", category: "Breakfast", time: 15, difficulty: "Easy", servings: 2, story: "The story of Classic French Toast started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://art.whisk.com/image/upload/fl_progressive%2Ch_560%2Cw_560%2Cc_fill%2Cdpr_2/v1762905710741/recipe/ae1148058a132ff01eaabc8a703c818a.jpg", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["breakfast","classic","flavorlyst"], ingredients: [{"q":2,"u":"slice","n":"bread"},{"q":2,"u":"egg","n":"eggs"},{"q":0.5,"u":"cup","n":"milk"},{"q":1,"u":"tsp","n":"cinnamon"},{"q":1,"u":"tbsp","n":"maple syrup"}], steps: ["In a shallow bowl, whisk the eggs, milk, cinnamon, and a small pinch of salt until the yolks and whites are fully combined.","Heat a skillet over medium to medium-low heat and melt a little butter, spreading it across the pan. The pan should sizzle gently but the butter should not burn.","Dip one slice of bread into the egg mixture for a few seconds per side, letting excess drip back into the bowl. Use sturdy bread and avoid soaking it until it falls apart.","Place the bread in the skillet and cook for about 2–3 minutes per side, turning once, until golden and the center is set. Cook in batches, adding a little butter as needed.","Serve hot with maple syrup. If the bread browns too quickly, reduce the heat so the egg mixture has time to cook through."] },
  { id: "r9", title: "Veggie Breakfast Burrito", category: "Breakfast", time: 18, difficulty: "Easy", servings: 2, story: "The story of Veggie Breakfast Burrito started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1626700051175-6818013e1d4f?auto=format&fit=crop&w=1200&q=85", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["breakfast","veggie","flavorlyst"], ingredients: [{"q":2,"u":"large","n":"tortillas"},{"q":3,"u":"egg","n":"eggs"},{"q":0.5,"u":"cup","n":"vegetables"},{"q":0.5,"u":"cup","n":"cheese"},{"q":1,"u":"tbsp","n":"oil"}], steps: ["Crack the eggs into a bowl and whisk with a pinch of salt and black pepper. Dice the bell pepper into small pieces so it softens quickly.","Heat a little oil or butter in a skillet over medium heat. Cook the pepper for 3–4 minutes until softened, then pour in the eggs.","Stir gently with a spatula for 2–3 minutes until the eggs form soft curds and are fully set. Remove from the heat and stir in the shredded cheese.","Warm each tortilla in a dry skillet for about 20–30 seconds per side until flexible. Divide the egg mixture between the tortillas and fold in the sides, then roll tightly.","Return the burritos seam-side down to the skillet over medium-low heat for 1–2 minutes per side to crisp the outside and melt the cheese. Serve warm."] },
  { id: "r10", title: "Cinnamon Apple Oatmeal", category: "Breakfast", time: 12, difficulty: "Easy", servings: 2, story: "The story of Cinnamon Apple Oatmeal started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://img.siterank.app/topic/cinnamon-apple-oatmeal-bowl-recipe.png", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["breakfast","cinnamon","flavorlyst"], ingredients: [{"q":1,"u":"cup","n":"oats"},{"q":2,"u":"cup","n":"milk"},{"q":1,"u":"","n":"apple"},{"q":1,"u":"tsp","n":"cinnamon"},{"q":1,"u":"tbsp","n":"honey"}], steps: ["Add the rolled oats and milk to a small saucepan. Bring to a gentle simmer over medium heat, stirring so the milk does not scorch.","Lower the heat to medium-low and stir in the diced apple and cinnamon. Cook for 5–7 minutes, stirring frequently, until the oats are creamy and the apple is tender. Add a splash of milk or water if it becomes too thick.","Taste the oats and add honey a little at a time for sweetness. For softer apple pieces, cook another 2–3 minutes; for more texture, stop when they are just tender.","Spoon into a bowl and let stand for 1 minute before eating, as the oatmeal will be very hot. Add a little extra milk if desired."] },
  { id: "r11", title: "Strawberry Chia Pudding", category: "Breakfast", time: 10, difficulty: "Easy", servings: 2, story: "The story of Strawberry Chia Pudding started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://static.wixstatic.com/media/a59d97_0f014a03ee1c4006baf5db02e476d6be~mv2.png/v1/fill/w_800%2Ch_1000%2Cal_c%2Cq_90%2Cusm_0.66_1.00_0.01/a59d97_0f014a03ee1c4006baf5db02e476d6be~mv2.png", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["breakfast","strawberry","flavorlyst"], ingredients: [{"q":0.25,"u":"cup","n":"chia seeds"},{"q":1,"u":"cup","n":"milk"},{"q":0.5,"u":"cup","n":"berries"},{"q":1,"u":"tsp","n":"honey"},{"q":0.25,"u":"tsp","n":"vanilla"}], steps: ["In a bowl or jar, whisk the chia seeds, milk, vanilla, and honey for 30–45 seconds so the seeds are evenly dispersed and do not clump.","Wait 5 minutes, then whisk again and stir in some of the berries. This second stir helps prevent a layer of chia seeds from settling at the bottom.","Cover and refrigerate for at least 2 hours, preferably overnight, until thick and spoonable. If it becomes too thick, stir in a splash of milk; if it is still runny, add 1 teaspoon chia seeds and chill longer.","Top with the remaining fresh berries before serving. Keep refrigerated and serve cold."] },
  { id: "r12", title: "Peanut Butter Banana Toast", category: "Breakfast", time: 7, difficulty: "Easy", servings: 2, story: "The story of Peanut Butter Banana Toast started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://pbs.twimg.com/media/F_Zbjw4XAAAEmVy.jpg", description: "A bright, comforting recipe made for easy home cooking.", tags: ["breakfast","peanut","flavorlyst"], ingredients: [{q:2,u:"slice",n:"bread"},{q:2,u:"tbsp",n:"peanut butter"},{q:1,u:"",n:"banana"},{q:1,u:"tsp",n:"honey"}], steps: ["Toast the bread until golden and crisp, using a toaster or a skillet over medium heat.","Spread the peanut butter evenly over the warm toast. If it is too thick to spread, stir it first or warm it briefly so it softens.","Peel and slice the banana into thin rounds, then arrange them over the peanut butter.","Drizzle with honey to taste and serve immediately. Keep an eye on the honey amount because a little goes a long way."] },
  { id: "r13", title: "Spinach Feta Omelet", category: "Breakfast", time: 12, difficulty: "Medium", servings: 2, story: "The story of Spinach Feta Omelet started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://snapcalorie-webflow-website.s3.us-east-2.amazonaws.com/media/food_pics_v2/medium/omelette_with_spinach_and_feta.jpg", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["breakfast","spinach","flavorlyst"], ingredients: [{q:3,u:"large",n:"eggs"},{q:1,u:"cup",n:"spinach"},{q:0.25,u:"cup",n:"feta cheese"},{q:1,u:"tsp",n:"olive oil"},{q:1,u:"pinch",n:"salt"}], steps: ["Crack the eggs into a bowl, add the listed salt and a little black pepper if available, and whisk until the whites and yolks are fully blended.","Heat the olive oil in a nonstick skillet over medium heat. Add the spinach and cook for 1–2 minutes, stirring, until wilted and any excess moisture has evaporated.","Reduce the heat to medium-low. Pour in the eggs and gently pull the cooked edges toward the center with a spatula while tilting the pan so uncooked egg flows underneath. Cook for 2–4 minutes until mostly set.","Scatter the feta over one half of the omelet. Fold the other half over the filling and cook for another 30–60 seconds, until the center is set and the feta is warm.","Slide onto a plate and serve immediately. Keep the heat moderate so the eggs stay tender instead of browning."] },
  { id: "r14", title: "Mango Coconut Smoothie", category: "Breakfast", time: 6, difficulty: "Medium", servings: 2, story: "The story of Mango Coconut Smoothie started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://naoq8gawh7kpd7sm.public.blob.vercel-storage.com/Mango%20smoothie%20recept-bqWDFsk2mMmQ8Hj988d1goAhD78u1O.webp", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["breakfast","mango","flavorlyst"], ingredients: [{q:1,u:"cup",n:"frozen mango"},{q:0.75,u:"cup",n:"coconut milk"},{q:0.5,u:"cup",n:"Greek yogurt"},{q:1,u:"tbsp",n:"lime juice"},{q:1,u:"tsp",n:"honey"}], steps: ["Add the frozen mango, coconut milk, Greek yogurt, lime juice, and honey to a blender in that order. Make sure the lid is secure before blending.","Blend for 30–60 seconds until smooth, stopping the blender to scrape down the sides if frozen mango pieces remain.","If the smoothie is too thick, add coconut milk 1 tablespoon at a time and blend again. If it is too tart, add a little more honey and blend briefly.","Pour into chilled glasses and serve immediately. Do not fill the blender past its recommended line."] },
  { id: "r15", title: "Savory Breakfast Hash", category: "Breakfast", time: 25, difficulty: "Easy", servings: 2, story: "The story of Savory Breakfast Hash started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://cupofyum.com/uploads/images/000/074/422/74422-breakfast-hash-cb64e195f782bfe4564a78a5af177b09.jpg", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["breakfast","savory","flavorlyst"], ingredients: [{q:2,u:"cup",n:"diced potatoes"},{q:1,u:"cup",n:"bell pepper"},{q:0.5,u:"cup",n:"onion"},{q:2,u:"large",n:"eggs"},{q:1,u:"tbsp",n:"olive oil"}], steps: ["Heat the olive oil in a large skillet over medium heat. Add the diced potatoes in an even layer and cook for 10–12 minutes, stirring every few minutes, until browned and nearly tender. If they stick or brown too quickly, lower the heat and add 1–2 tablespoons water, then cover for 2 minutes.","Add the diced onion and bell pepper. Cook for 4–5 minutes, stirring occasionally, until the vegetables soften. Season with salt and black pepper if available.","Make two small wells in the potato mixture and crack an egg into each well. Cover the skillet and cook over medium-low heat for 4–7 minutes, checking often, until the whites are set and the yolks reach your preferred doneness.","Make sure the eggs are cooked safely; for fully set eggs, cook until both the whites and yolks are firm. Serve hot straight from the skillet."] },
  { id: "r16", title: "Chocolate Chip Waffles", category: "Breakfast", time: 22, difficulty: "Medium", servings: 2, story: "The story of Chocolate Chip Waffles started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://media-assets.swiggy.com/swiggy/image/upload/f_auto%2Cq_auto%2Cfl_lossy/RX_THUMBNAIL/IMAGES/VENDOR/2025/5/30/2884d4ad-64ab-44f3-9329-f6f27f1657f2_1093096.jpg", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["breakfast","chocolate","flavorlyst"], ingredients: [{q:2,u:"cup",n:"flour"},{q:1.5,u:"cup",n:"milk"},{q:2,u:"large",n:"eggs"},{q:0.75,u:"cup",n:"chocolate chips"},{q:2,u:"tbsp",n:"melted butter"},{q:1,u:"tbsp",n:"sugar"}], steps: ["Preheat the waffle iron according to its manufacturer's directions. In a large bowl, whisk together the flour and sugar.","In another bowl, whisk the milk and eggs, then whisk in the melted butter once it has cooled slightly. Pour the wet ingredients into the dry ingredients and stir just until combined; do not overmix.","Fold the chocolate chips through the batter. Lightly grease the hot waffle iron if its instructions recommend it.","Pour in enough batter to cover the center without overflowing. Close the lid and cook for about 3–5 minutes, or until the steam slows and the waffle is crisp and golden. Timing varies by waffle iron.","Carefully remove the waffle with a silicone or wooden utensil. Repeat with the remaining batter and serve warm."] },
  { id: "r17", title: "Greek Yogurt Parfait", category: "Breakfast", time: 8, difficulty: "Medium", servings: 2, story: "The story of Greek Yogurt Parfait started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://snapcalorie-webflow-website.s3.us-east-2.amazonaws.com/media/food_pics_v2/medium/greek_yogurt_parfait.jpg", description: "A bright, comforting recipe made for easy home cooking.", tags: ["breakfast","greek","flavorlyst"], ingredients: [{q:2,u:"cup",n:"Greek yogurt"},{q:1,u:"cup",n:"berries"},{q:0.5,u:"cup",n:"granola"},{q:1,u:"tbsp",n:"honey"}], steps: ["Spoon half of the Greek yogurt into two clean glasses or bowls and spread it into an even layer.","Add a layer of washed, dried berries, followed by a layer of granola. Keep the granola near serving time if you want it to stay crunchy.","Add the remaining yogurt and repeat the fruit and granola layers.","Drizzle with honey to taste and serve immediately, or cover and refrigerate briefly. For best texture, add the granola just before eating."] },
  { id: "r18", title: "Breakfast Quesadilla", category: "Breakfast", time: 15, difficulty: "Easy", servings: 2, story: "The story of Breakfast Quesadilla started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://www.tastingtable.com/img/gallery/the-best-way-to-cook-your-eggs-for-a-savory-breakfast-quesadilla/intro-1713881170.jpg", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["breakfast","breakfast","flavorlyst"], ingredients: [{q:4,u:"large",n:"eggs"},{q:2,u:"large",n:"flour tortillas"},{q:0.75,u:"cup",n:"shredded cheese"},{q:0.25,u:"cup",n:"diced bell pepper"},{q:1,u:"tbsp",n:"butter"}], steps: ["Whisk the eggs in a bowl with a pinch of salt and black pepper if available. Dice the bell pepper into small pieces.","Melt a little butter in a skillet over medium heat. Cook the pepper for 3–4 minutes, then add the eggs and stir gently until the eggs are just set, about 2–3 minutes. Transfer to a plate.","Place a tortilla in the skillet over medium-low heat. Sprinkle cheese over one half, spoon the egg mixture on top, then add a little more cheese so it helps hold the filling together.","Fold the tortilla in half and cook for 2–3 minutes per side, pressing gently with a spatula, until the outside is golden and the cheese has melted. Lower the heat if it browns too quickly.","Repeat with the second tortilla. Let each quesadilla rest for 1 minute, then cut into wedges and serve warm."] },
  { id: "r19", title: "Maple Pecan Oatmeal", category: "Breakfast", time: 12, difficulty: "Medium", servings: 2, story: "The story of Maple Pecan Oatmeal started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://snapcalorie-webflow-website.s3.us-east-2.amazonaws.com/media/recipe_pics_v2/medium/maple_brown_sugar_oatmeal.jpg", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["breakfast","maple","flavorlyst"], ingredients: [{q:1,u:"cup",n:"rolled oats"},{q:2,u:"cup",n:"milk"},{q:0.25,u:"cup",n:"pecans"},{q:2,u:"tbsp",n:"maple syrup"},{q:0.5,u:"tsp",n:"cinnamon"}], steps: ["Add the rolled oats, milk, and cinnamon to a small saucepan. Stir and bring to a gentle simmer over medium heat.","Reduce the heat to medium-low and cook for 5–7 minutes, stirring often, until the oats are soft and creamy. Add a splash more milk if the mixture becomes too thick.","Stir in the maple syrup and taste. Add a little more cinnamon or syrup if desired.","Spoon into bowls and top with pecans. For a stronger nutty flavor, toast the pecans in a dry skillet over medium-low heat for 2–3 minutes, stirring constantly, before adding them."] },
  { id: "r20", title: "Berry Banana Smoothie", category: "Breakfast", time: 7, difficulty: "Easy", servings: 2, story: "The story of Berry Banana Smoothie started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://forktionary.s3.us-east-2.amazonaws.com/prod/images/recipe-image-16158.png", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["breakfast","berry","flavorlyst"], ingredients: [{q:1,u:"cup",n:"mixed berries"},{q:1,u:"large",n:"banana"},{q:1,u:"cup",n:"milk"},{q:0.5,u:"cup",n:"Greek yogurt"},{q:1,u:"tsp",n:"honey"}], steps: ["Add the mixed berries, peeled banana, milk, Greek yogurt, and honey to a blender. If using frozen berries, the smoothie will be thicker and colder.","Secure the lid and blend for 30–60 seconds until smooth. Stop and scrape down the sides if fruit sticks above the blades.","Add milk 1 tablespoon at a time if the smoothie is too thick, or add a few more berries if you want it thicker. Blend briefly after each adjustment.","Pour into glasses and serve immediately. Refrigerate leftovers promptly and shake or stir before drinking."] },
  { id: "r21", title: "Tomato Egg Toast", category: "Breakfast", time: 12, difficulty: "Easy", servings: 2, story: "The story of Tomato Egg Toast started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://mealprepedia.com/wp-content/uploads/2025/06/Tomato-Basil-Egg-Toast.webp", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["breakfast","tomato","flavorlyst"], ingredients: [{q:2,u:"slice",n:"bread"},{q:2,u:"large",n:"eggs"},{q:1,u:"",n:"tomato"},{q:1,u:"tbsp",n:"olive oil"},{q:1,u:"tbsp",n:"fresh basil"}], steps: ["Toast the bread until golden and crisp. Rinse the tomato and basil, then slice the tomato into thin rounds.","Heat the olive oil in a nonstick skillet over medium-low heat. Crack in the eggs and cook for 3–5 minutes for sunny-side-up eggs, or gently turn and cook longer for firmer yolks. Season with salt and black pepper if available.","Arrange the tomato slices on the toast and place the cooked eggs on top. If you prefer softer tomato, warm the slices in the skillet for 30 seconds first.","Tear the basil leaves over the top and serve immediately. For food safety, cook eggs until the whites are set and yolks reach the desired safe doneness."] },
  { id: "r22", title: "Turkey Pesto Sandwich", category: "Lunch", time: 12, difficulty: "Medium", servings: 2, story: "The story of Turkey Pesto Sandwich started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://d1w7312wesee68.cloudfront.net/uHCHaSjsChGJoBO2piPvxwnQ_PEntfm_JsYabDeBsDc/resize%3Afit%3A720%3A720/plain/s3%3A/toasttab/menu_service/restaurants/ccbe2d96-d203-46b9-a3dc-f86ca6184c6e/MenuItem/46a91df6-1b6f-44b1-bdad-1985da30d465.jpg", description: "A bright, comforting recipe made for easy home cooking.", tags: ["lunch","turkey","flavorlyst"], ingredients: [{"q":4,"u":"slice","n":"bread"},{"q":4,"u":"oz","n":"turkey"},{"q":2,"u":"tbsp","n":"pesto"},{"q":0.5,"u":"cup","n":"tomato"},{"q":1,"u":"cup","n":"greens"}], steps: ["Lay out the bread, sliced turkey, pesto, and any listed cheese or vegetables. If the bread is very soft, lightly toast it first so it holds the filling.","Spread about 1 tablespoon pesto over each sandwich's inner bread surface. Spread it evenly to the edges without soaking the bread.","Layer the turkey evenly over two slices of bread. Add the other listed fillings, distributing them so every bite has a little of each ingredient.","Close the sandwiches, press gently, and cut in half. For a warm sandwich, toast in a skillet over medium-low heat for 2–3 minutes per side until the bread is golden and the filling is warmed through.","Serve immediately. Pesto is flavorful and salty, so taste before adding extra salt."] },
  { id: "r23", title: "Caprese Pasta Salad", category: "Lunch", time: 18, difficulty: "Medium", servings: 2, story: "The story of Caprese Pasta Salad started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://www.feastingathome.com/wp-content/uploads/2023/06/caprese-pasta-salad-11.jpg", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["lunch","caprese","flavorlyst"], ingredients: [{"q":8,"u":"oz","n":"pasta"},{"q":1,"u":"cup","n":"tomatoes"},{"q":1,"u":"cup","n":"mozzarella"},{"q":0.25,"u":"cup","n":"basil"},{"q":2,"u":"tbsp","n":"olive oil"}], steps: ["Bring a pot of water to a boil, salt it, and cook the pasta according to the package directions until just tender. Reserve 1/4 cup of pasta water, then drain and rinse briefly under cool water to stop the cooking for a cold salad.","While the pasta cooks, halve the tomatoes and cut the mozzarella into bite-size pieces. Tear or slice the fresh basil.","In a large bowl, whisk the olive oil with a little salt and black pepper. Add the pasta, tomatoes, mozzarella, and basil, then toss gently until coated.","Taste and adjust with more pepper or a small splash of olive oil. If the salad seems dry, add reserved pasta water 1 tablespoon at a time, only as needed.","Chill for 10 minutes if time allows, or serve at room temperature. Refrigerate leftovers within 2 hours."] },
  { id: "r24", title: "Chicken Caesar Wrap", category: "Lunch", time: 20, difficulty: "Medium", servings: 2, story: "The story of Chicken Caesar Wrap started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://www.therandomrecipe.com/_next/image?q=75&url=https%3A%2F%2Fd2aq0yf1s46hyj.cloudfront.net%2Ftherandomrecipe%2F205.png&w=3840", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["lunch","chicken","flavorlyst"], ingredients: [{"q":2,"u":"large","n":"tortillas"},{"q":8,"u":"oz","n":"chicken"},{"q":2,"u":"cup","n":"romaine"},{"q":0.25,"u":"cup","n":"Parmesan"},{"q":3,"u":"tbsp","n":"dressing"}], steps: ["Pat the chicken dry and season both sides with salt and black pepper if available. Heat a lightly oiled skillet over medium heat.","Cook the chicken for about 5–7 minutes per side, depending on thickness, until the center reaches 165°F (74°C). Transfer to a clean plate and rest for 5 minutes, then slice thinly.","Warm the tortillas for 15–20 seconds per side in a dry skillet so they bend without cracking. Rinse and dry the romaine, then chop it into bite-size pieces.","Place romaine, sliced chicken, Parmesan, and Caesar dressing in a bowl and toss until lightly coated. Avoid adding too much dressing at once; the wrap should not be soggy.","Divide the filling between the tortillas, fold in the sides, and roll tightly. Slice in half and serve immediately."] },
  { id: "r25", title: "Tomato Basil Grilled Cheese", category: "Lunch", time: 15, difficulty: "Easy", servings: 2, story: "The story of Tomato Basil Grilled Cheese started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1606070781631-a7e961f84c9e?auto=format&fit=crop&w=1200&q=85", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["lunch","tomato","flavorlyst"], ingredients: [{"q":4,"u":"slice","n":"bread"},{"q":2,"u":"slice","n":"cheese"},{"q":1,"u":"","n":"tomato"},{"q":0.25,"u":"cup","n":"basil"},{"q":1,"u":"tbsp","n":"butter"}], steps: ["Slice the tomato thinly and pat the slices dry with a paper towel to reduce moisture. Tear or chop the basil leaves.","Butter one side of each bread slice. Place two slices butter-side down in a skillet over medium-low heat.","Layer the cheese, tomato, and basil onto the bread in the skillet, then top with the remaining bread slices butter-side up.","Cook for 3–5 minutes per side, pressing gently with a spatula, until the bread is deep golden and the cheese is melted. Turn the heat down if the bread browns before the cheese melts.","Rest for 1 minute, cut in half, and serve warm. Keep tomato slices thin so the sandwich heats evenly."] },
  { id: "r26", title: "Mediterranean Hummus Bowl", category: "Lunch", time: 15, difficulty: "Easy", servings: 2, story: "The story of Mediterranean Hummus Bowl started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=1200&q=85", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["lunch","mediterranean","flavorlyst"], ingredients: [{"q":1,"u":"cup","n":"cooked grains"},{"q":0.5,"u":"cup","n":"hummus"},{"q":0.5,"u":"cup","n":"cucumber"},{"q":0.5,"u":"cup","n":"tomato"},{"q":1,"u":"tbsp","n":"lemon juice"}], steps: ["Prepare the cooked grains according to their package directions if they are not already cooked. Fluff with a fork and let them cool slightly so the hummus does not become watery.","Dice the cucumber and tomato into bite-size pieces. If the tomato is very juicy, remove some of the seeds or drain it briefly.","Divide the grains between two bowls. Add a generous spoonful of hummus to each bowl, then arrange the cucumber and tomato around it.","Drizzle the lemon juice over the vegetables and grains. Add black pepper and a pinch of salt if available, tasting first because hummus can already be salty.","Serve at room temperature or slightly chilled. Stir the hummus through the grains as you eat."] },
  { id: "r27", title: "Creamy Broccoli Soup", category: "Lunch", time: 30, difficulty: "Easy", servings: 2, story: "The story of Creamy Broccoli Soup started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1528735602780-2552fd46c7b?auto=format&fit=crop&w=1200&q=85", description: "A bright, comforting recipe made for easy home cooking.", tags: ["lunch","creamy","flavorlyst"], ingredients: [{q:4,u:"cup",n:"broccoli florets"},{q:1,u:"small",n:"onion"},{q:3,u:"cup",n:"vegetable broth"},{q:0.5,u:"cup",n:"cream"},{q:1,u:"tbsp",n:"olive oil"}], steps: ["Chop the onion into small pieces and cut the broccoli into similar-sized florets. Heat the olive oil in a large pot over medium heat.","Add the onion and cook for 4–5 minutes, stirring, until soft and translucent but not browned. Add the broccoli and vegetable broth.","Bring the broth to a gentle boil, then reduce to a simmer. Cover and cook for 10–15 minutes, until the broccoli is very tender when pierced with a fork.","Turn off the heat and blend until smooth using an immersion blender. If using a countertop blender, blend in small batches and vent the lid carefully because hot soup can splatter.","Return the soup to low heat and stir in the cream. Warm for 1–2 minutes without boiling, then season with salt and black pepper to taste. Add a splash of broth if it is too thick."] },
  { id: "r28", title: "Tuna Crunch Sandwich", category: "Lunch", time: 10, difficulty: "Easy", servings: 2, story: "The story of Tuna Crunch Sandwich started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1582034986517-30d163aa1da9?auto=format&fit=crop&w=1200&q=85", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["lunch","tuna","flavorlyst"], ingredients: [{q:2,u:"can",n:"tuna"},{q:4,u:"slice",n:"bread"},{q:2,u:"tbsp",n:"mayonnaise"},{q:0.5,u:"cup",n:"celery"},{q:0.25,u:"cup",n:"pickles"}], steps: ["Drain the tuna thoroughly and flake it into a bowl with a fork. Finely chop the celery and pickles so they mix evenly through the filling.","Add the mayonnaise, celery, and pickles to the tuna. Stir until combined, breaking up large tuna pieces but keeping some texture.","Taste the mixture before seasoning; pickles are salty and tangy. Add black pepper and, if needed, a small pinch of salt or a little extra pickle juice.","Toast the bread if you want extra crunch. Divide the tuna mixture between two slices and spread it evenly, then close with the remaining bread.","Cut the sandwiches in half and serve immediately. Keep the tuna mixture refrigerated if not serving right away."] },
  { id: "r29", title: "Rainbow Veggie Wrap", category: "Lunch", time: 12, difficulty: "Easy", servings: 2, story: "The story of Rainbow Veggie Wrap started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=1200&q=85", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["lunch","rainbow","flavorlyst"], ingredients: [{q:2,u:"large",n:"flour tortillas"},{q:0.5,u:"cup",n:"hummus"},{q:1,u:"cup",n:"shredded lettuce"},{q:0.5,u:"cup",n:"bell pepper"},{q:0.5,u:"cup",n:"cucumber"},{q:0.5,u:"cup",n:"carrot"}], steps: ["Rinse and dry the lettuce, bell pepper, cucumber, and carrot. Shred the lettuce, slice the pepper and cucumber into thin strips, and grate or julienne the carrot.","Lay the tortillas flat and spread hummus over the center of each one, leaving about a 1-inch border around the edges.","Divide the vegetables between the tortillas, placing the firmer strips across the middle. Do not overfill or the tortillas may split when rolled.","Fold the left and right sides inward, then roll from the bottom up tightly around the filling. If a tortilla cracks, warm it in a dry skillet for 10–15 seconds per side to make it more flexible.","Cut each wrap in half on a diagonal and serve immediately. For packed lunches, wrap tightly and keep chilled."] },
  { id: "r30", title: "Lemon Herb Couscous", category: "Lunch", time: 15, difficulty: "Easy", servings: 2, story: "The story of Lemon Herb Couscous started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://domesticate-me.com/wp-content/uploads/2021/04/Lemon-Herb-Couscous-1.jpg", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["lunch","lemon","flavorlyst"], ingredients: [{q:1,u:"cup",n:"couscous"},{q:1,u:"cup",n:"vegetable broth"},{q:1,u:"tbsp",n:"olive oil"},{q:1,u:"tbsp",n:"lemon juice"},{q:2,u:"tbsp",n:"fresh herbs"}], steps: ["Pour the vegetable broth into a small saucepan and bring it to a boil. Stir in the couscous, then immediately remove the pan from the heat and cover with a lid.","Let stand for 5 minutes, or for the time printed on the couscous package. Keep the lid on so the couscous absorbs the broth evenly.","Fluff the couscous with a fork to separate the grains. Stir in the olive oil and lemon juice while it is still warm.","Finely chop the fresh herbs and fold them through the couscous. Taste and add black pepper and salt if needed; the broth may already be seasoned.","Serve warm or at room temperature. If it seems dry, add another teaspoon of olive oil or lemon juice and fluff again."] },
  { id: "r31", title: "Southwest Chicken Salad", category: "Lunch", time: 20, difficulty: "Easy", servings: 2, story: "The story of Southwest Chicken Salad started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://recipesbybianca.com/assets/images/1768707024409-4ujxiae4.webp", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["lunch","southwest","flavorlyst"], ingredients: [{q:1,u:"lb",n:"chicken breast"},{q:4,u:"cup",n:"mixed greens"},{q:0.5,u:"cup",n:"corn"},{q:0.5,u:"cup",n:"black beans"},{q:0.5,u:"cup",n:"tomato"},{q:2,u:"tbsp",n:"lime dressing"}], steps: ["Pat the chicken breast dry. Season both sides with salt, black pepper, and a little paprika or cumin if available. Heat a lightly oiled skillet over medium heat.","Cook the chicken for about 5–7 minutes per side, depending on thickness, until the center reaches 165°F (74°C). Transfer to a clean plate, rest for 5 minutes, then slice across the grain.","Rinse and dry the mixed greens and tomato. Drain and rinse the black beans, and drain the corn if canned. Place the greens, beans, corn, and chopped tomato in a large bowl.","Arrange the sliced chicken over the salad. Drizzle with the lime dressing a little at a time and toss gently just before serving.","Taste and adjust with extra lime juice or black pepper if desired. Serve immediately so the greens stay crisp."] },
  { id: "r32", title: "Margherita Flatbread", category: "Lunch", time: 20, difficulty: "Easy", servings: 2, story: "The story of Margherita Flatbread started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://storage.googleapis.com/fpoo-public-bucket/img/Recipes/flatbread-margherita.jpg", description: "A bright, comforting recipe made for easy home cooking.", tags: ["lunch","margherita","flavorlyst"], ingredients: [{q:1,u:"large",n:"flatbread"},{q:0.5,u:"cup",n:"tomato sauce"},{q:1,u:"cup",n:"fresh mozzarella"},{q:0.25,u:"cup",n:"fresh basil"},{q:1,u:"tbsp",n:"olive oil"}], steps: ["Heat the oven to 425°F (220°C), or follow the flatbread package's temperature if it specifies one. Place the flatbread on a baking sheet.","Spread the tomato sauce in a thin, even layer, leaving a small border around the edge so the crust can crisp.","Tear or slice the fresh mozzarella and distribute it over the sauce. Add only some of the basil before baking if you want a few leaves to retain their fresh flavor.","Bake for 8–12 minutes, checking at 8 minutes, until the edges are crisp and the cheese is melted and bubbling. The time depends on the thickness of the flatbread.","Remove carefully, scatter the remaining basil over the top, and drizzle with olive oil. Rest for 1 minute, slice, and serve hot."] },
  { id: "r33", title: "Greek Chicken Pita", category: "Lunch", time: 25, difficulty: "Easy", servings: 2, story: "The story of Greek Chicken Pita started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://cdn.juliesdish.com/images/featured_image_row_4_a490f1a7-dc.jpg?w=1920", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["lunch","greek","flavorlyst"], ingredients: [{q:2,u:"large",n:"pita breads"},{q:1,u:"lb",n:"chicken"},{q:0.5,u:"cup",n:"cucumber"},{q:0.5,u:"cup",n:"tomato"},{q:0.25,u:"cup",n:"tzatziki"}], steps: ["Cut the chicken into thin strips or small even pieces. Season with salt, black pepper, and dried oregano or paprika if available.","Heat a little oil in a skillet over medium heat. Cook the chicken for 5–7 minutes, stirring or turning occasionally, until browned and the thickest pieces reach 165°F (74°C). Rest for 3 minutes.","While the chicken cooks, dice the cucumber and tomato. Warm the pita breads in a dry skillet for 20–30 seconds per side or wrap them in foil in a 300°F (150°C) oven for about 5 minutes.","Open each pita carefully and fill with chicken, cucumber, and tomato. Spoon tzatziki over the filling; use a little first so the pita does not become soggy.","Serve immediately. Keep any unused tzatziki refrigerated."] },
  { id: "r34", title: "Cucumber Feta Salad", category: "Lunch", time: 10, difficulty: "Easy", servings: 2, story: "The story of Cucumber Feta Salad started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1572453800999-e8d2d1589b7a?auto=format&fit=crop&w=1200&q=85", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["lunch","cucumber","flavorlyst"], ingredients: [{q:2,u:"cup",n:"cucumber"},{q:1,u:"cup",n:"tomato"},{q:0.5,u:"cup",n:"feta cheese"},{q:0.25,u:"cup",n:"red onion"},{q:1,u:"tbsp",n:"olive oil"}], steps: ["Rinse and dry the cucumber and tomato. Cut the cucumber and tomato into bite-size pieces, and slice the red onion very thinly.","Put the vegetables in a bowl and crumble the feta over them.","Drizzle with olive oil and add black pepper and a small pinch of salt if needed. Feta is salty, so taste before adding much salt.","Toss gently so the feta does not completely break down. Let stand for 5 minutes to let the flavors mingle, then serve."] },
  { id: "r35", title: "Garlic Butter Shrimp", category: "Dinner", time: 15, difficulty: "Medium", servings: 2, story: "The story of Garlic Butter Shrimp started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1644898955763-682dbe5127ac?auto=format&fit=crop&w=1200&q=85", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["dinner","garlic","flavorlyst"], ingredients: [{q:1,u:"lb",n:"shrimp"},{q:3,u:"tbsp",n:"butter"},{q:4,u:"clove",n:"garlic"},{q:1,u:"tbsp",n:"lemon juice"},{q:2,u:"tbsp",n:"fresh parsley"}], steps: ["Pat the shrimp dry with paper towels. If they are shell-on, peel and devein them first. Season lightly with salt and black pepper if available.","Melt the butter in a large skillet over medium heat. Add the minced garlic and cook for 30–45 seconds, stirring constantly until fragrant; do not let it turn dark brown.","Add the shrimp in a single layer. Cook about 1–2 minutes per side, depending on size, until they turn pink and opaque and reach 145°F (63°C). Avoid overcooking, which makes shrimp rubbery.","Turn the heat to low and stir in the lemon juice and chopped parsley. Toss for 20–30 seconds to coat the shrimp in the garlic butter.","Taste the sauce and adjust with lemon, salt, or pepper. Serve immediately with rice, pasta, or bread if desired."] },
  { id: "r36", title: "Chicken Tikka Rice Bowls", category: "Dinner", time: 35, difficulty: "Medium", servings: 2, story: "The story of Chicken Tikka Rice Bowls started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://sweetbananachef.com/wp-content/uploads/2025/06/0-1-640-N-151.jpg", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["dinner","chicken","flavorlyst"], ingredients: [{q:1,u:"lb",n:"chicken"},{q:2,u:"cup",n:"cooked rice"},{q:0.5,u:"cup",n:"yogurt"},{q:2,u:"tbsp",n:"tikka masala"},{q:0.5,u:"cup",n:"tomato sauce"}], steps: ["Cut the chicken into even bite-size pieces. In a bowl, mix the yogurt with the tikka masala seasoning or paste, then add the chicken and coat thoroughly. Marinate for at least 10 minutes, or refrigerate for up to overnight.","Heat a lightly oiled skillet over medium-high heat. Lift the chicken from the marinade, letting excess drip off, and cook in a single layer for 6–10 minutes, stirring occasionally, until browned and the thickest pieces reach 165°F (74°C). Cook in batches if necessary.","Pour the tomato sauce into the skillet and stir to coat the chicken. Reduce the heat to medium-low and simmer for 5–8 minutes, stirring occasionally, until the sauce is hot and slightly thickened.","Warm the cooked rice according to its package instructions. If using refrigerated rice, heat until steaming hot throughout.","Spoon rice into bowls and top with the chicken and sauce. Taste and add a little salt or extra tikka seasoning if needed."] },
  { id: "r37", title: "Beef & Broccoli Stir-Fry", category: "Dinner", time: 25, difficulty: "Medium", servings: 2, story: "The story of Beef & Broccoli Stir-Fry started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://eatthegains.com/wp-content/uploads/2018/09/Beef-and-Broccoli-10.jpg", description: "A bright, comforting recipe made for easy home cooking.", tags: ["dinner","beef","flavorlyst"], ingredients: [{q:1,u:"lb",n:"beef"},{q:3,u:"cup",n:"broccoli"},{q:2,u:"tbsp",n:"soy sauce"},{q:1,u:"tbsp",n:"sesame oil"},{q:2,u:"clove",n:"garlic"}], steps: ["Slice the beef thinly across the grain; partially freezing it for 15–20 minutes first can make slicing easier. Cut the broccoli into small florets and mince the garlic.","Heat the sesame oil in a large skillet or wok over high heat until shimmering. Add the beef in a single layer and sear for 1–2 minutes per side until browned. Transfer to a plate; it can finish cooking when returned to the pan.","Add the broccoli and 2 tablespoons water to the hot pan. Stir-fry for 3–5 minutes until bright green and tender-crisp. Add the garlic and cook for 30 seconds, stirring constantly.","Return the beef and any juices to the pan. Add the soy sauce and toss for 1–2 minutes until the beef is cooked to your preferred safe doneness and the sauce coats everything. Add a splash of water if the pan is dry.","Serve hot over rice if desired. Soy sauce is salty, so taste before adding extra salt."] },
  { id: "r38", title: "Baked Pesto Salmon", category: "Dinner", time: 25, difficulty: "Medium", servings: 2, story: "The story of Baked Pesto Salmon started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://cupofyum.com/uploads/images/000/021/579/21579-pesto-salmon-sheet-pan-meal-4fe8f82801c910660a5d4a8c40a55abd.jpg", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["dinner","baked","flavorlyst"], ingredients: [{q:1,u:"lb",n:"salmon"},{q:0.25,u:"cup",n:"pesto"},{q:1,u:"tbsp",n:"lemon juice"},{q:1,u:"tbsp",n:"olive oil"},{q:1,u:"cup",n:"cherry tomatoes"}], steps: ["Heat the oven to 400°F (200°C). Line a baking sheet with parchment or lightly oil it. Pat the salmon dry and place it skin-side down if it has skin.","Brush the top of each salmon portion with pesto. Halve the cherry tomatoes and scatter them around the fish; drizzle the tomatoes with a little olive oil and season lightly with black pepper.","Bake for 12–16 minutes depending on the thickness of the salmon. It is done when it flakes easily and reaches 145°F (63°C) at the thickest point; thicker fillets may need a few extra minutes.","Remove from the oven and squeeze lemon juice over the salmon. Let rest for 2 minutes before serving.","Serve with the roasted tomatoes and any pan juices. Check early rather than overbaking, because salmon continues to cook briefly after leaving the oven."] },
  { id: "r39", title: "One-Pan Sausage & Peppers", category: "Dinner", time: 30, difficulty: "Medium", servings: 2, story: "The story of One-Pan Sausage & Peppers started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://i.pinimg.com/736x/3e/1c/23/3e1c23c98e9fe96a1fe4454224eaacf4.jpg", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["dinner","one-pan","flavorlyst"], ingredients: [{q:1,u:"lb",n:"sausage"},{q:2,u:"",n:"bell peppers"},{q:1,u:"",n:"onion"},{q:1,u:"tbsp",n:"olive oil"},{q:1,u:"tsp",n:"Italian seasoning"}], steps: ["Heat the oven to 425°F (220°C) if roasting, or use a large skillet over medium heat if cooking on the stovetop. Slice the sausage into coins or bite-size pieces; slice the bell peppers and onion into strips.","Toss the sausage, peppers, and onion with olive oil and Italian seasoning. Add black pepper and a little salt if desired, remembering that sausage can already be salty.","For oven cooking, spread everything in one layer on a rimmed baking sheet and roast for 20–25 minutes, stirring halfway through. For stovetop cooking, sauté for 15–20 minutes, stirring often, until the vegetables soften and the sausage is browned.","Check the sausage package for its safe internal temperature; raw pork or beef sausage should reach 160°F (71°C), and poultry sausage 165°F (74°C). Fully cooked sausage should be heated until steaming hot.","Serve hot on its own, over rice, or in rolls. If the pan looks dry during stovetop cooking, add a tablespoon of water and cover briefly."] },
  { id: "r40", title: "Vegetable Curry", category: "Dinner", time: 35, difficulty: "Medium", servings: 2, story: "The story of Vegetable Curry started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://itsonly.recipes/images/recipeimages/vegetable-curry.webp", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["dinner","vegetable","flavorlyst"], ingredients: [{q:1,u:"cup",n:"chickpeas"},{q:1,u:"cup",n:"potatoes"},{q:1,u:"cup",n:"mixed vegetables"},{q:1,u:"cup",n:"coconut milk"},{q:1,u:"tbsp",n:"curry powder"}], steps: ["Drain and rinse the chickpeas. Peel and dice the potatoes into small, even cubes so they cook in the same amount of time. Cut any larger mixed vegetables into bite-size pieces.","Warm a little oil in a deep skillet or saucepan over medium heat if available. Add the curry powder and stir for 20–30 seconds until fragrant, taking care not to burn it.","Add the potatoes and mixed vegetables and stir to coat with the spices. Pour in the coconut milk and add the chickpeas. If the liquid does not nearly cover the potatoes, add a splash of water or broth.","Bring to a gentle simmer, then reduce the heat to medium-low. Cook uncovered for 15–20 minutes, stirring every few minutes, until the potatoes are fork-tender and the sauce thickens. Add a little water if it becomes too thick before the potatoes cook.","Taste and adjust the curry powder, salt, and black pepper. Serve hot over rice or with flatbread if desired."] },
  { id: "r41", title: "Classic Beef Tacos", category: "Dinner", time: 20, difficulty: "Medium", servings: 2, story: "The story of Classic Beef Tacos started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://myhomemademeal.com/assets/images/1747159667177-7jkkf3cv.webp", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["dinner","classic","flavorlyst"], ingredients: [{q:1,u:"lb",n:"ground beef"},{q:8,u:"small",n:"corn tortillas"},{q:1,u:"tbsp",n:"taco seasoning"},{q:1,u:"cup",n:"shredded lettuce"},{q:0.5,u:"cup",n:"shredded cheese"}], steps: ["Heat a large skillet over medium-high heat. Add the ground beef and break it into small crumbles with a wooden spoon. Cook for 6–8 minutes, stirring, until no pink remains and the beef reaches 160°F (71°C).","If there is a large amount of grease, carefully drain it from the pan. Stir in the taco seasoning and the amount of water listed on its packet; if using homemade seasoning, start with 2–3 tablespoons water.","Simmer for 2–3 minutes, stirring, until the seasoning coats the beef and the liquid thickens. Taste before adding salt because taco seasoning can be salty.","Warm the corn tortillas in a dry skillet over medium heat for about 20–30 seconds per side, or wrap in a damp paper towel and microwave briefly until flexible.","Fill each tortilla with the seasoned beef, shredded lettuce, and cheese. Add other toppings if desired and serve immediately."] },
  { id: "r42", title: "Creamy Lemon Chicken", category: "Dinner", time: 30, difficulty: "Medium", servings: 2, story: "The story of Creamy Lemon Chicken started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://img.siterank.app/topic/home-cooked-lemon-chicken-dish-recipe.png", description: "A bright, comforting recipe made for easy home cooking.", tags: ["dinner","creamy","flavorlyst"], ingredients: [{q:1,u:"lb",n:"chicken breast"},{q:0.5,u:"cup",n:"heavy cream"},{q:1,u:"",n:"lemon"},{q:2,u:"clove",n:"garlic"},{q:0.5,u:"cup",n:"chicken broth"},{q:1,u:"tbsp",n:"olive oil"}], steps: ["Pat the chicken breasts dry. If they are thick, slice horizontally or gently pound to an even thickness. Season both sides with salt and black pepper if available.","Heat the olive oil in a skillet over medium heat. Add the chicken and sear for 4–6 minutes per side until golden; transfer briefly to a plate. The chicken will finish cooking in the sauce.","Reduce the heat to medium-low. Add the minced garlic and cook for about 30 seconds until fragrant. Pour in the chicken broth and scrape the browned bits from the bottom of the pan.","Stir in the heavy cream and add the chicken back to the skillet. Simmer gently for 5–8 minutes, turning once, until the thickest part of the chicken reaches 165°F (74°C) and the sauce has slightly thickened. Do not boil hard.","Stir in lemon juice a little at a time, tasting as you go. Adjust salt and pepper and serve with the sauce spooned over the chicken."] },
  { id: "r43", title: "Spinach Ricotta Stuffed Shells", category: "Dinner", time: 50, difficulty: "Medium", servings: 2, story: "The story of Spinach Ricotta Stuffed Shells started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://d1yfn1dfres2va.cloudfront.net/013/e1/16/e116e9908d54fc540870bdf16ffb4d60_640m.jpg", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["dinner","spinach","flavorlyst"], ingredients: [{q:12,u:"",n:"jumbo pasta shells"},{q:1.5,u:"cup",n:"ricotta"},{q:1,u:"cup",n:"spinach"},{q:1.5,u:"cup",n:"marinara sauce"},{q:0.75,u:"cup",n:"mozzarella"}], steps: ["Heat the oven to 375°F (190°C). Bring a large pot of salted water to a boil and cook the jumbo shells for about 2 minutes less than the package's full cooking time; they should be flexible but still firm. Drain carefully and spread on a tray to cool slightly.","Thaw frozen spinach completely and squeeze out excess water, or cook fresh spinach until wilted and let it cool. Chop it, then mix with the ricotta and a pinch of salt and black pepper if available.","Spread a thin layer of marinara sauce over the bottom of a baking dish. Fill each shell with the ricotta-spinach mixture using a spoon and arrange them open-side up in the dish.","Spoon the remaining marinara over and around the shells, then sprinkle mozzarella evenly over the top. Cover the dish loosely with foil.","Bake covered for 20 minutes, then uncover and bake another 10–15 minutes until the sauce bubbles and the cheese melts. Let stand for 5 minutes before serving because the filling will be very hot."] },
  { id: "r44", title: "Honey Garlic Salmon", category: "Dinner", time: 25, difficulty: "Medium", servings: 2, story: "The story of Honey Garlic Salmon started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://hips.hearstapps.com/hmg-prod/images/1506456214-delish-honey-garlic-glazed-salmon-1662057850.jpg?crop=1xw%3A1xh%3Bcenter%2Ctop&resize=980%3A%2A", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["dinner","honey","flavorlyst"], ingredients: [{q:1,u:"lb",n:"salmon"},{q:3,u:"tbsp",n:"honey"},{q:2,u:"clove",n:"garlic"},{q:1,u:"tbsp",n:"soy sauce"},{q:1,u:"tbsp",n:"lemon juice"}], steps: ["Heat the oven to 400°F (200°C). Lightly oil a baking dish and pat the salmon dry. Place the fillets in the dish skin-side down if they have skin.","In a small bowl, whisk together the honey, minced garlic, soy sauce, and lemon juice until the honey loosens and the mixture is smooth.","Spoon or brush the glaze over the salmon, reserving a little to brush on near the end if desired. Bake for 12–16 minutes depending on thickness, basting once halfway through.","Check the thickest part with a food thermometer; salmon should reach 145°F (63°C) and flake easily. If the glaze starts darkening too quickly, loosely cover the dish with foil.","Rest for 2 minutes, spoon the pan glaze over the fish, and serve warm. The soy sauce is salty, so extra salt is usually unnecessary."] },
  { id: "r45", title: "Veggie Fried Rice", category: "Dinner", time: 20, difficulty: "Medium", servings: 2, story: "The story of Veggie Fried Rice started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://snapcalorie-webflow-website.s3.us-east-2.amazonaws.com/media/food_pics_v2/medium/veg_fried_rice.jpg", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["dinner","veggie","flavorlyst"], ingredients: [{q:3,u:"cup",n:"cooked rice"},{q:1,u:"cup",n:"mixed vegetables"},{q:2,u:"large",n:"eggs"},{q:2,u:"tbsp",n:"soy sauce"},{q:1,u:"tbsp",n:"sesame oil"}], steps: ["Use cold, cooked rice if possible; freshly cooked rice can turn sticky, so spread it on a tray and let it cool briefly. Break up any clumps with a fork.","Heat the sesame oil in a large skillet or wok over medium-high heat. Add the mixed vegetables and stir-fry for 3–5 minutes until hot and tender-crisp.","Push the vegetables to one side. Add the eggs to the empty side and scramble for 1–2 minutes until fully set, then mix them through the vegetables.","Add the rice and soy sauce. Stir-fry for 3–5 minutes, breaking up clumps and tossing often, until the rice is steaming hot throughout. If the pan is crowded, cook in batches.","Taste before adding salt because soy sauce is salty. Serve immediately, and refrigerate leftovers within 2 hours."] },
  { id: "r46", title: "Chicken Parmesan", category: "Dinner", time: 45, difficulty: "Medium", servings: 2, story: "The story of Chicken Parmesan started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://itsonly.recipes/images/recipeimages/heritage-chicken-parmigiana.webp", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["dinner","chicken","flavorlyst"], ingredients: [{q:1,u:"lb",n:"chicken breast"},{q:0.5,u:"cup",n:"breadcrumbs"},{q:1,u:"cup",n:"marinara sauce"},{q:1,u:"cup",n:"mozzarella"},{q:0.25,u:"cup",n:"Parmesan"}], steps: ["Heat the oven to 400°F (200°C). If the chicken breasts are thick, pound them to an even 1/2-inch thickness so they cook evenly. Pat dry and season both sides with salt and black pepper if available.","Put the breadcrumbs in a shallow dish. Press each chicken piece into the crumbs, coating both sides and pressing gently so they stick. If the coating does not adhere, lightly dampen the chicken with a little water or beaten egg if available.","Heat a thin layer of olive oil in an oven-safe skillet over medium heat. Cook the chicken for about 3–4 minutes per side until the crumbs are golden; it does not need to be fully cooked yet.","Spoon marinara over each piece and top with mozzarella and Parmesan. Transfer the skillet to the oven, or move the chicken to a baking dish.","Bake for 8–12 minutes, until the cheese is melted and the thickest part of the chicken reaches 165°F (74°C). Rest for 3 minutes before serving."] },
  { id: "r47", title: "Black Bean Enchiladas", category: "Dinner", time: 40, difficulty: "Medium", servings: 2, story: "The story of Black Bean Enchiladas started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://itsonly.recipes/images/recipeimages/chipotle-black-bean-enchiladas.webp", description: "A bright, comforting recipe made for easy home cooking.", tags: ["dinner","black","flavorlyst"], ingredients: [{q:2,u:"cup",n:"black beans"},{q:8,u:"small",n:"corn tortillas"},{q:1.5,u:"cup",n:"enchilada sauce"},{q:1,u:"cup",n:"shredded cheese"},{q:0.5,u:"cup",n:"corn"}], steps: ["Heat the oven to 375°F (190°C). Drain and rinse the black beans, then place them in a bowl with the corn. Mash about one-third of the beans with a fork so the filling holds together; season with cumin, chili powder, and black pepper if available.","Warm the corn tortillas in a dry skillet for 15–20 seconds per side or wrap them in a damp paper towel and microwave briefly. Warm tortillas are less likely to crack when rolled.","Spread a thin layer of enchilada sauce over the bottom of a baking dish. Spoon the bean mixture down the center of each tortilla, roll it snugly, and place seam-side down in the dish.","Pour the remaining enchilada sauce evenly over the rolls, making sure the edges are covered so they do not dry out. Sprinkle the shredded cheese over the top.","Cover with foil and bake for 15 minutes, then uncover and bake another 5–10 minutes until the sauce bubbles and the cheese melts. Rest for 5 minutes before serving; the filling will be hot."] },
  { id: "r48", title: "Creamy Garlic Parmesan Chicken", category: "Dinner", time: 30, difficulty: "Medium", servings: 2, story: "The story of Creamy Garlic Parmesan Chicken started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://www.thecookingrecipes.com/wp-content/uploads/2025/07/creamy-garlic-chicken-skillet-recipe-with-herb-sauce.webp", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["dinner","creamy","flavorlyst"], ingredients: [{q:1,u:"lb",n:"chicken breast"},{q:0.5,u:"cup",n:"heavy cream"},{q:0.5,u:"cup",n:"Parmesan"},{q:4,u:"clove",n:"garlic"},{q:1,u:"tbsp",n:"olive oil"}], steps: ["Pat the chicken dry and season both sides with salt and black pepper if available. If the breasts are thick, slice horizontally or pound them to an even thickness.","Heat the olive oil in a large skillet over medium heat. Sear the chicken for 4–6 minutes per side until golden. Transfer to a clean plate; it will finish cooking in the sauce.","Reduce the heat to medium-low. Add the minced garlic and cook for 30 seconds, stirring so it does not brown. Pour in the heavy cream and scrape up the browned bits from the pan.","Stir in the grated Parmesan a handful at a time until melted. Return the chicken and any juices to the skillet, then simmer gently for 5–8 minutes, turning once, until the chicken reaches 165°F (74°C) and the sauce thickens.","If the sauce becomes too thick, stir in 1–2 tablespoons water. Taste before adding salt because Parmesan is salty, then serve hot with sauce spooned over the chicken."] },
  { id: "r49", title: "Miso Glazed Eggplant", category: "Dinner", time: 30, difficulty: "Medium", servings: 2, story: "The story of Miso Glazed Eggplant started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.mrcook.app/recipe-image/018fd9d1-0e95-7d40-b5c2-da70f64e5502", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["dinner","miso","flavorlyst"], ingredients: [{q:1,u:"large",n:"eggplant"},{q:2,u:"tbsp",n:"miso paste"},{q:1,u:"tbsp",n:"soy sauce"},{q:1,u:"tbsp",n:"maple syrup"},{q:1,u:"tsp",n:"sesame oil"}], steps: ["Heat the oven to 400°F (200°C). Cut the eggplant in half lengthwise and score the cut flesh in a crosshatch pattern without cutting through the skin.","In a small bowl, whisk the miso paste, soy sauce, maple syrup, and sesame oil until smooth. If the miso is very thick, add 1 teaspoon water to make it easier to brush.","Place the eggplant halves cut-side up on a lined baking sheet. Brush about half the glaze over the scored flesh, working it into the cuts.","Roast for 20–25 minutes, then brush with the remaining glaze and roast another 5–10 minutes until the flesh is very tender and the top is browned in spots. Larger eggplants may need more time.","Let rest for 2 minutes before serving. Taste before adding salt because both miso and soy sauce are salty."] },
  { id: "r50", title: "Pesto Gnocchi", category: "Dinner", time: 20, difficulty: "Medium", servings: 2, story: "The story of Pesto Gnocchi started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://bitsandbitesblog.com/wp-content/uploads/2023/04/pesto-gnocchi-recipe-5-of-6-700x1050.jpg", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["dinner","pesto","flavorlyst"], ingredients: [{q:1,u:"lb",n:"gnocchi"},{q:0.5,u:"cup",n:"pesto"},{q:0.5,u:"cup",n:"cherry tomatoes"},{q:0.25,u:"cup",n:"Parmesan"},{q:1,u:"tbsp",n:"olive oil"}], steps: ["Bring a pot of water to a boil. Add the gnocchi and cook according to the package directions; many shelf-stable gnocchi are done when they float, but follow the package timing. Drain, reserving a few tablespoons of cooking water.","While the gnocchi cooks, warm the olive oil in a skillet over medium heat. Add the halved cherry tomatoes and cook for 3–4 minutes until they soften and release some juice.","Lower the heat and stir in the pesto. Warm gently for 1 minute; do not let it fry or the basil flavor can dull. Add a splash of gnocchi water to loosen the sauce if needed.","Add the drained gnocchi and toss gently for 1–2 minutes until coated. Stir in the Parmesan and taste before adding salt, as pesto and cheese are already salty.","Serve hot with extra Parmesan if desired."] },
  { id: "r51", title: "Sheet-Pan Lemon Chicken", category: "Dinner", time: 35, difficulty: "Medium", servings: 2, story: "The story of Sheet-Pan Lemon Chicken started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://v.cdn.ww.com/media/system/wine/625d997905d20000104b3464/4075a9f9-eb2a-41a5-b295-21f8b7f0a6c2/y9kcevu6v0ubvlfwcykx.jpg?auto=webp&enable=upscale&fit=crop&height=800&optimize=medium&quality=80&width=800", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["dinner","sheet-pan","flavorlyst"], ingredients: [{q:1,u:"lb",n:"chicken thighs"},{q:2,u:"",n:"lemons"},{q:1,u:"lb",n:"potatoes"},{q:2,u:"cup",n:"vegetables"},{q:2,u:"tbsp",n:"olive oil"}], steps: ["Heat the oven to 425°F (220°C). Line a large rimmed baking sheet with foil or parchment. Cut the potatoes and other vegetables into similar bite-size pieces; slice the lemons into rounds or wedges.","Place the chicken thighs, potatoes, vegetables, and lemon on the tray. Drizzle with olive oil and season with salt, black pepper, and dried thyme, rosemary, or paprika if available. Toss the vegetables well and rub the oil and seasoning over the chicken.","Arrange everything in a single layer, leaving space between pieces so they roast rather than steam. Roast for 30–40 minutes, turning the vegetables halfway through. If the tray is crowded, use two trays.","Check the chicken with a thermometer at the thickest part, avoiding the bone; it must reach at least 165°F (74°C). Thighs often become more tender around 175–185°F (79–85°C). Potatoes should be fork-tender and vegetables browned.","Rest the chicken for 5 minutes before serving. If the vegetables need more color after the chicken is cooked, remove the chicken to a plate and roast the vegetables for another 5 minutes."] },
  { id: "r52", title: "Butternut Squash Pasta", category: "Dinner", time: 35, difficulty: "Medium", servings: 2, story: "The story of Butternut Squash Pasta started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://snapcalorie-webflow-website.s3.us-east-2.amazonaws.com/media/recipe_pics_v2/medium/pasta_with_roasted_butternut_squash_and_sage.jpg", description: "A bright, comforting recipe made for easy home cooking.", tags: ["dinner","butternut","flavorlyst"], ingredients: [{q:8,u:"oz",n:"pasta"},{q:2,u:"cup",n:"butternut squash"},{q:0.5,u:"cup",n:"vegetable broth"},{q:0.25,u:"cup",n:"Parmesan"},{q:1,u:"tbsp",n:"sage"}], steps: ["Heat the oven to 425°F (220°C). Peel the butternut squash, remove the seeds, and cut the flesh into 1/2-inch cubes. Toss with a little olive oil, salt, and black pepper if available, spread on a baking sheet, and roast for 20–25 minutes until fork-tender. (Alternatively, sauté covered in a skillet with a splash of water until soft.)","Meanwhile, bring a pot of salted water to a boil and cook the pasta according to the package directions until al dente. Reserve 1 cup of pasta water, then drain.","Blend the cooked squash with the vegetable broth until smooth. If using a countertop blender, let the squash cool slightly and blend in batches; hot ingredients can create pressure.","Pour the squash purée into a skillet over medium-low heat. Stir in the Parmesan and chopped sage, then add the pasta and toss. Add reserved pasta water a little at a time until the sauce clings to the pasta.","Taste and adjust salt and black pepper. Warm gently for 1–2 minutes and serve hot; do not boil hard after adding the cheese."] },
  { id: "r53", title: "Teriyaki Chicken Bowls", category: "Dinner", time: 30, difficulty: "Medium", servings: 2, story: "The story of Teriyaki Chicken Bowls started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://melorecipes.com/wp-content/uploads/2025/06/teriyaki-chicken-bowl-2025-06-11-105009.webp", description: "A simple favorite designed for relaxed meals and busy days.", tags: ["dinner","teriyaki","flavorlyst"], ingredients: [{q:1,u:"lb",n:"chicken"},{q:2,u:"cup",n:"cooked rice"},{q:0.5,u:"cup",n:"teriyaki sauce"},{q:1,u:"cup",n:"broccoli"},{q:1,u:"tbsp",n:"sesame seeds"}], steps: ["Cut the chicken into even bite-size pieces and pat dry. If desired, season lightly with black pepper; teriyaki sauce is usually salty.","Heat a lightly oiled skillet over medium-high heat. Add the chicken in a single layer and cook for 5–8 minutes, turning occasionally, until browned and the thickest pieces reach 165°F (74°C). Cook in batches if the pan is crowded.","Reduce the heat to medium-low and pour in the teriyaki sauce. Stir and simmer for 2–4 minutes until the sauce bubbles gently and coats the chicken. If it becomes too thick, add 1–2 tablespoons water.","Warm the cooked rice and steam or microwave the broccoli until tender but still bright green. If using frozen broccoli, follow the package directions and heat until steaming hot.","Divide the rice and broccoli between bowls and spoon the chicken and sauce over them. Sprinkle with sesame seeds and serve immediately."] },
  { id: "r54", title: "Baked Ziti", category: "Dinner", time: 50, difficulty: "Medium", servings: 2, story: "The story of Baked Ziti started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1677511084683-0eba66ebaa7c?auto=format&fit=crop&w=1200&q=85", description: "A colorful dish that turns everyday ingredients into something special.", tags: ["dinner","baked","flavorlyst"], ingredients: [{q:12,u:"oz",n:"ziti pasta"},{q:2,u:"cup",n:"marinara sauce"},{q:1.5,u:"cup",n:"ricotta"},{q:1.5,u:"cup",n:"mozzarella"},{q:0.5,u:"cup",n:"Parmesan"}], steps: ["Heat the oven to 375°F (190°C). Bring a large pot of salted water to a boil and cook the ziti for about 2 minutes less than the package's suggested time; it will continue cooking in the oven. Drain well.","In a large bowl, mix the drained pasta with the marinara sauce and ricotta until evenly coated. If the ricotta is very firm, stir it first so it distributes more easily.","Spread half the pasta mixture in a baking dish. Sprinkle with some mozzarella and Parmesan, add the remaining pasta, then finish with the remaining cheeses. Cover loosely with foil.","Bake covered for 20 minutes, then remove the foil and bake another 10–15 minutes until the sauce bubbles around the edges and the cheese is melted and lightly golden.","Let stand for 5–10 minutes before serving so the sauce settles and the pasta is easier to scoop. The dish will be very hot immediately from the oven."] },
  { id: "r55", title: "Coconut Chickpea Curry", category: "Dinner", time: 30, difficulty: "Easy", servings: 2, story: "The story of Coconut Chickpea Curry started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1627906296851-6d9c5e4db592?auto=format&fit=crop&w=1200&q=85", description: "A cozy recipe with familiar flavors and a little Flavorlyst magic.", tags: ["dinner","coconut","flavorlyst"], ingredients: [{q:2,u:"can",n:"chickpeas"},{q:1,u:"cup",n:"coconut milk"},{q:1,u:"cup",n:"tomato sauce"},{q:1,u:"cup",n:"spinach"},{q:1,u:"tbsp",n:"curry powder"}], steps: ["Drain and rinse the chickpeas. Heat a little oil in a saucepan over medium heat if available. Add the curry powder and stir for 20–30 seconds until fragrant, taking care not to burn it.","Add the tomato sauce and coconut milk, stirring until the sauce is evenly colored. Add the chickpeas and bring the mixture to a gentle simmer.","Reduce the heat to medium-low and simmer uncovered for 12–18 minutes, stirring every few minutes, until the sauce thickens slightly and the chickpeas are hot throughout. Add a splash of water if it gets too thick.","Stir in the spinach a handful at a time and cook for 1–2 minutes until wilted. Taste and adjust curry powder, salt, and black pepper as needed.","Serve hot over rice or with flatbread. Let leftovers cool promptly and refrigerate in a covered container."] },
  { id: "r56", title: "BBQ Chicken Flatbread", category: "Dinner", time: 25, difficulty: "Easy", servings: 2, story: "The story of BBQ Chicken Flatbread started with a home cook looking for a meal that felt special without being complicated. It became a repeat favorite because the ingredients are familiar, the process is approachable, and the finished dish is worth gathering around the table for. This Flavorlyst version keeps that easygoing spirit.", author: "Flavorlyst Kitchen", image: "https://images.unsplash.com/photo-1579751626657-72bc17010498?auto=format&fit=crop&w=1200&q=85", description: "A fresh, satisfying idea that is easy to make and fun to share.", tags: ["dinner","bbq","flavorlyst"], ingredients: [{q:1,u:"large",n:"flatbread"},{q:1,u:"cup",n:"cooked chicken"},{q:0.5,u:"cup",n:"BBQ sauce"},{q:0.75,u:"cup",n:"shredded mozzarella"},{q:0.25,u:"cup",n:"red onion"}], steps: ["Heat the oven to 425°F (220°C), or follow the flatbread package's temperature if specified. Place the flatbread on a baking sheet.","Spread the BBQ sauce over the flatbread in a thin, even layer, leaving a small border around the edge.","Scatter the cooked chicken and thinly sliced red onion over the sauce, then sprinkle the mozzarella evenly over the top. Make sure the chicken is already fully cooked before assembling.","Bake for 8–12 minutes, checking at 8 minutes, until the edges are crisp and the cheese is melted and bubbling. If the crust browns too quickly, lower the oven to 400°F (200°C).","Let cool for 1–2 minutes so the cheese sets slightly, then slice and serve. Add a little extra BBQ sauce after baking if desired."] },

  { id: "r57", title: "Cinnamon Sugar Popcorn", category: "Snacks", time: 8, difficulty: "Easy", servings: 2,
    story: "A simple snack can still feel special. This popcorn pairs warm cinnamon with a little sweetness for a quick treat that is easy to make when movie night or an afternoon break calls for something cozy.",
    author: "Flavorlyst Kitchen", description: "Warm cinnamon sugar popcorn with a light, sweet crunch.",
    tags: ["snack","popcorn","quick"], ingredients: [{q:6,u:"cup",n:"popcorn"},{q:2,u:"tbsp",n:"butter"},{q:2,u:"tbsp",n:"sugar"},{q:0.5,u:"tsp",n:"cinnamon"},{q:1,u:"pinch",n:"salt"}],
    steps: ["Put the popped popcorn in a large heat-safe bowl and remove any unpopped kernels.","Melt the butter in a small saucepan over low heat or in a microwave-safe bowl in short 10–15 second bursts, stirring between bursts.","In a small bowl, mix the sugar, cinnamon, and salt. Drizzle the melted butter over the popcorn while tossing, then sprinkle on the cinnamon-sugar mixture a little at a time and toss again so it distributes evenly.","Taste and add a little more cinnamon sugar if desired. Let stand for 1 minute so the coating settles, then serve. The popcorn is best the same day because moisture can soften it."]
  },
  { id: "r58", title: "Apple Cinnamon Snack Bites", category: "Snacks", time: 15, difficulty: "Easy", servings: 2,
    story: "These little bites were inspired by the classic combination of apples and cinnamon. They are designed for a quick snack that feels homemade without requiring a complicated recipe.",
    author: "Flavorlyst Kitchen", description: "Soft apple and oat bites with cozy cinnamon flavor.",
    tags: ["snack","apple","oat"], ingredients: [{q:1,u:"",n:"apple"},{q:1,u:"cup",n:"rolled oats"},{q:1,u:"tbsp",n:"honey"},{q:0.5,u:"tsp",n:"cinnamon"},{q:1,u:"tbsp",n:"butter"}],
    steps: ["Heat the oven to 350°F (175°C). Line a baking sheet with parchment paper. Finely grate or dice the apple; if it is very juicy, gently blot excess moisture with a paper towel.","Put the apple, rolled oats, honey, cinnamon, and melted butter in a bowl. Stir thoroughly until the oats are evenly moistened and the mixture holds together when pressed. If it seems too wet, add 1–2 tablespoons extra oats.","With slightly damp hands, shape the mixture into small 1-inch balls or compact bites. Place them on the lined tray with a little space between each and gently press to help them hold their shape.","Bake for 12–16 minutes, until the outside looks set and lightly golden. Let the bites cool on the tray for 10 minutes; they firm up as they cool.","Serve warm or cool completely and store covered in the refrigerator because the recipe contains fresh apple. For a softer, no-bake texture, refrigerate shaped bites instead of baking, but keep them chilled."]
  },
  { id: "r59", title: "Cheesy Tortilla Crisps", category: "Snacks", time: 12, difficulty: "Easy", servings: 2,
    story: "This snack turns a few everyday ingredients into crisp, cheesy bites. It is the kind of recipe that works whenever you want something warm and crunchy without a long cooking session.",
    author: "Flavorlyst Kitchen", description: "Crispy tortilla pieces covered with melted cheese.",
    tags: ["snack","cheese","quick"], ingredients: [{q:2,u:"large",n:"flour tortillas"},{q:0.75,u:"cup",n:"shredded cheese"},{q:1,u:"tbsp",n:"olive oil"},{q:0.5,u:"tsp",n:"paprika"}],
    steps: ["Heat the oven to 375°F (190°C). Line a baking sheet with parchment paper. Stack the tortillas and cut them into triangles or bite-size squares.","Put the tortilla pieces in a bowl and drizzle with the olive oil. Sprinkle with paprika and toss well so each piece gets a thin coating. Add a pinch of salt if available.","Spread the pieces in a single layer on the tray; overlapping pieces will steam instead of crisp. Sprinkle the shredded cheese evenly over them.","Bake for 8–12 minutes, checking at 6 minutes, until the edges are crisp and the cheese is melted. Thin pieces can burn quickly, so remove browned pieces early if needed.","Cool on the tray for 2–3 minutes to let them crisp further, then serve. They are best fresh; re-crisp leftovers in a 350°F (175°C) oven for 3–4 minutes."]
  },
  { id: "r60", title: "Chocolate Chip Cookies", category: "Desserts", time: 25, difficulty: "Easy", servings: 12,
    story: "Few desserts are as recognizable as a warm chocolate chip cookie. This Flavorlyst version keeps the process straightforward, with crisp edges, a soft center, and plenty of chocolate chips.",
    author: "Flavorlyst Kitchen", description: "Classic chocolate chip cookies with golden edges.",
    tags: ["dessert","cookie","chocolate"], ingredients: [{q:1.5,u:"cup",n:"flour"},{q:0.5,u:"cup",n:"butter"},{q:0.5,u:"cup",n:"brown sugar"},{q:1,u:"large",n:"egg"},{q:1,u:"cup",n:"chocolate chips"}],
    steps: ["Heat the oven to 350°F (175°C). Line a baking sheet with parchment paper. Let the butter soften until it yields to a gentle press but is not melted.","In a bowl, beat the softened butter and brown sugar together for 2–3 minutes until creamy and slightly lighter. Add the egg and mix until smooth, scraping down the sides of the bowl.","Add the flour and stir just until no dry patches remain. Fold in the chocolate chips. Do not overmix or the cookies can become tough. If the dough feels very soft, chill it for 10–15 minutes.","Scoop tablespoon-sized portions onto the baking sheet, leaving about 2 inches between them. Bake for 9–12 minutes until the edges are golden and the centers still look slightly soft.","Leave the cookies on the tray for 5 minutes to firm up, then transfer to a rack to cool. If baking a second tray, let the baking sheet cool first so the cookies do not spread too quickly."]
  },
  { id: "r61", title: "Berry Yogurt Bark", category: "Desserts", time: 10, difficulty: "Easy", servings: 4,
    story: "Yogurt bark is a freezer-friendly dessert that turns a few simple ingredients into something fun to break apart and share. Berries add bright flavor while a little honey brings everything together.",
    author: "Flavorlyst Kitchen", description: "Frozen yogurt bark with berries and a touch of honey.",
    tags: ["dessert","berry","yogurt"], ingredients: [{q:2,u:"cup",n:"Greek yogurt"},{q:1,u:"cup",n:"berries"},{q:2,u:"tbsp",n:"honey"},{q:0.25,u:"cup",n:"granola"}],
    steps: ["Line a small rimmed tray or plate that fits in your freezer with parchment paper. Stir the Greek yogurt until smooth; if desired, mix in a little honey to sweeten it evenly.","Spread the yogurt into an even layer about 1/4 inch thick. A thinner layer freezes faster and breaks into crisp pieces; a thicker layer will be easier to bite.","Scatter the berries over the yogurt and drizzle with honey. Sprinkle the granola on top, pressing it gently into the surface so it sticks.","Freeze flat for at least 3–4 hours, until completely firm. If the tray is uneven, the bark may freeze at different speeds; check the center before removing it.","Break into pieces and serve straight from the freezer. Yogurt bark melts quickly, so return leftovers to a sealed freezer-safe container immediately."]
  },
  { id: "r62", title: "Mini Chocolate Brownies", category: "Desserts", time: 30, difficulty: "Medium", servings: 9,
    story: "These brownies are built for the classic chocolate-dessert craving: rich cocoa flavor, a tender center, and a simple baking process that makes a small batch.",
    author: "Flavorlyst Kitchen", description: "Small-batch chocolate brownies with a rich, fudgy center.",
    tags: ["dessert","brownie","chocolate"], ingredients: [{q:0.5,u:"cup",n:"flour"},{q:0.5,u:"cup",n:"sugar"},{q:0.25,u:"cup",n:"cocoa powder"},{q:0.25,u:"cup",n:"butter"},{q:1,u:"large",n:"egg"}],
    steps: ["Heat the oven to 350°F (175°C). Grease or line a small 8-inch square baking pan with parchment, leaving a little overhang so the brownies can be lifted out later.","Melt the butter in a microwave-safe bowl in 15–20 second bursts or in a small saucepan over low heat. Let it cool for 3–5 minutes so it is warm but not hot.","Whisk the sugar and egg into the melted butter until smooth and glossy. Stir in the cocoa powder and flour just until no dry streaks remain; do not overmix.","Spread the batter evenly in the prepared pan. Bake for 18–24 minutes, checking at 18 minutes. The edges should look set and a toothpick inserted near the center should come out with moist crumbs, not wet batter.","Cool in the pan for at least 20 minutes before cutting. Brownies continue to set as they cool, so avoid baking until the center looks completely dry."]
  },
  { id: "r63", title: "Strawberry Shortcake Cups", category: "Desserts", time: 20, difficulty: "Easy", servings: 4,
    story: "Strawberry shortcake is a celebration of simple layers. These individual cups combine tender cake, juicy strawberries, and a creamy topping for a dessert that looks special without being complicated.",
    author: "Flavorlyst Kitchen", description: "Layered strawberry shortcake served in individual cups.",
    tags: ["dessert","strawberry","cake"], ingredients: [{q:2,u:"cup",n:"strawberries"},{q:2,u:"cup",n:"shortcake"},{q:1,u:"cup",n:"whipped cream"},{q:1,u:"tbsp",n:"sugar"}],
    steps: ["Rinse, dry, and hull the strawberries. Slice them into small pieces, place in a bowl, and toss with the sugar. Let stand for 10–15 minutes until the berries release a little juice.","Cut the shortcake into bite-size cubes. If the shortcake is very soft, use a serrated knife and a gentle sawing motion so it does not crumble.","Place a layer of shortcake pieces in the bottom of each cup. Spoon some strawberries and their juice over the cake, then add a layer of whipped cream.","Repeat the layers, finishing with whipped cream and a few strawberry pieces on top. Do not press the layers down, or the cups can become dense.","Serve right away, or cover and refrigerate for up to 2 hours. Longer chilling softens the shortcake, which some people enjoy but reduces its texture."]
  },
  { id: "r64", title: "Cinnamon Apple Crisp", category: "Desserts", time: 40, difficulty: "Easy", servings: 6,
    story: "Apple crisp is the kind of dessert that fills the kitchen with the smell of cinnamon and baked fruit. This version keeps the topping simple so the apples stay the star of the dish.",
    author: "Flavorlyst Kitchen", description: "Baked cinnamon apples beneath a golden oat topping.",
    tags: ["dessert","apple","cinnamon"], ingredients: [{q:4,u:"",n:"apples"},{q:1,u:"cup",n:"rolled oats"},{q:0.5,u:"cup",n:"flour"},{q:0.5,u:"cup",n:"brown sugar"},{q:0.5,u:"cup",n:"butter"},{q:1,u:"tsp",n:"cinnamon"}],
    steps: ["Heat the oven to 350°F (175°C). Lightly butter a medium baking dish. Peel the apples if desired, remove the cores, and slice them about 1/4 inch thick so they soften evenly.","Put the apple slices in a bowl and toss with the cinnamon. If the apples are very tart, add a spoonful of the brown sugar from the topping ingredients; arrange the apples in the baking dish.","In another bowl, combine the rolled oats, flour, and brown sugar. Add the butter in small pieces and rub it into the dry ingredients with your fingertips or a fork until the mixture forms moist crumbs with some pea-size pieces.","Scatter the topping evenly over the apples without pressing it down. Bake for 30–40 minutes, until the topping is golden and the apple juices bubble around the edges. If the top browns too quickly, loosely cover with foil.","Let the crisp rest for at least 10 minutes before serving; the fruit filling is extremely hot and thickens as it cools. Serve warm on its own or with yogurt or ice cream if desired."]
  },
];

