const getAutomaticRecipeImage = (title, ingredients = []) => {
  const searchText = ((title || "") + " " + ingredients.map(i => i.n || "").join(" ")).toLowerCase();
  const match = recipeImageChoices.find(choice => choice.words.test(searchText));
  return match?.image || "https://images.unsplash.com/photo-1623052935410-3fca63f73e10?auto=format&fit=crop&w=1200&q=85";
};

const addMissingRecipeImages = list => Array.isArray(list)
  ? list.map(recipe => {
      if (!recipe) return recipe;
      if (curatedStarterRecipeImages[recipe.id]) return {...recipe, image: curatedStarterRecipeImages[recipe.id]};
      return recipe.image ? recipe : {...recipe, image: getAutomaticRecipeImage(recipe.title || "", recipe.ingredients || [])};
    })
  : list;

const initialPlanner = {
  Monday: "r1", Tuesday: "r2", Wednesday: null, Thursday: "r4", Friday: null, Saturday: "r6", Sunday: null
};

function load(key, fallback) {
  try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; } catch { return fallback; }
}
function save(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); } catch {} }

function normalizeRecipe(recipe) {
  if (!recipe || typeof recipe !== "object") return null;
  const title = String(recipe.title || "Untitled Recipe").trim();
  const ingredients = Array.isArray(recipe.ingredients)
    ? recipe.ingredients.map(i => ({
        q: Number(i?.q) || 1,
        u: String(i?.u || ""),
        n: String(i?.n || "").trim()
      })).filter(i => i.n)
    : [];
  const steps = Array.isArray(recipe.steps)
    ? recipe.steps.map(s => String(s || "").trim()).filter(Boolean)
    : [];
  const tags = Array.isArray(recipe.tags)
    ? recipe.tags.map(t => String(t || "").toLowerCase().trim()).filter(Boolean)
    : title.toLowerCase().split(/\s+/).filter(Boolean).slice(0, 4);
  return {
    ...recipe,
    title,
    description: String(recipe.description || ""),
    category: ["Breakfast","Lunch","Dinner","Snacks","Desserts"].includes(recipe.category) ? recipe.category : "Dinner",
    time: Math.max(1, Number(recipe.time) || 30),
    difficulty: ["Easy","Medium","Hard"].includes(recipe.difficulty) ? recipe.difficulty : "Easy",
    servings: Math.max(1, Number(recipe.servings) || 2),
    author: String(recipe.author || "Flavorlyst Kitchen"),
    story: String(recipe.story || ""),
    tags,
    ingredients,
    steps
  };
}

function normalizeRecipes(list) {
  return Array.isArray(list) ? list.map(normalizeRecipe).filter(Boolean) : starterRecipes.map(normalizeRecipe);
}

function mergeStarterRecipes(list) {
  const existing = Array.isArray(list) ? list : [];
  const existingIds = new Set(existing.map(recipe => recipe?.id));
  return [...existing, ...starterRecipes.filter(recipe => !existingIds.has(recipe.id))];
}

function App() {
  const [recipes, setRecipes] = useState(() => normalizeRecipes(addMissingRecipeImages(mergeStarterRecipes(load("recipe-recipes", starterRecipes)))));
  const [favorites, setFavorites] = useState(() => {
    const value = load("recipe-favorites", ["r1","r5"]);
    return Array.isArray(value) ? value : ["r1","r5"];
  });
  const [planner, setPlanner] = useState(() => {
    const value = load("recipe-planner", initialPlanner);
    return value && typeof value === "object" && !Array.isArray(value) ? value : initialPlanner;
  });
  const [view, setView] = useState("home");
  const [previousView, setPreviousView] = useState("home");
  const [selected, setSelected] = useState(null);
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("All");
  const [timeFilter, setTimeFilter] = useState("Any");
  const [difficultyFilter, setDifficultyFilter] = useState("Any");
  const [dietFilter, setDietFilter] = useState("All");
  const [sortFilter, setSortFilter] = useState("Recommended");
  const [showFilters, setShowFilters] = useState(false);
  const [servings, setServings] = useState(2);
  const [showInstall, setShowInstall] = useState(false);
  const [installPrompt, setInstallPrompt] = useState(null);
  const [darkMode, setDarkMode] = useState(() => Boolean(load("flavorlyst-dark-mode", false)));
  const [newRecipe, setNewRecipe] = useState({title:"",description:"",category:"Dinner",time:30,difficulty:"Easy",servings:2,image:"",ingredients:"",steps:""});
  const [aiStatus, setAiStatus] = useState("");

  useEffect(() => {
    const handleInstallPrompt = e => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener("beforeinstallprompt", handleInstallPrompt);
    return () => window.removeEventListener("beforeinstallprompt", handleInstallPrompt);
  }, []);

  useEffect(() => {
    const current = normalizeRecipes(mergeStarterRecipes(load("recipe-recipes", starterRecipes)));
    const upgraded = addMissingRecipeImages(current);
    if (JSON.stringify(upgraded) !== JSON.stringify(current)) {
      save("recipe-recipes", upgraded);
      setRecipes(upgraded);
    }

    const validIds = new Set(upgraded.map(r => r.id));
    const storedFavorites = load("recipe-favorites", ["r1","r5"]);
    const cleanFavorites = Array.isArray(storedFavorites) ? storedFavorites.filter(id => validIds.has(id)) : [];
    if (JSON.stringify(cleanFavorites) !== JSON.stringify(storedFavorites)) {
      save("recipe-favorites", cleanFavorites);
      setFavorites(cleanFavorites);
    }

    const storedPlanner = load("recipe-planner", initialPlanner);
    const cleanPlanner = storedPlanner && typeof storedPlanner === "object"
      ? Object.fromEntries(Object.entries(storedPlanner).map(([day,id]) => [day, validIds.has(id) ? id : null]))
      : initialPlanner;
    if (JSON.stringify(cleanPlanner) !== JSON.stringify(storedPlanner)) {
      save("recipe-planner", cleanPlanner);
      setPlanner(cleanPlanner);
    }
  }, []);

  
  const categories = ["All","Breakfast","Lunch","Dinner","Snacks","Desserts"];
  const filtered = useMemo(() => {
    let result = recipes.filter(r => {
      const q = search.toLowerCase().trim();
      const matchesText = !q || r.title.toLowerCase().includes(q) || (r.tags || []).some(t => t.includes(q)) || (r.ingredients || []).some(i => i.n.toLowerCase().includes(q));
      const matchesCategory = category === "All" || r.category === category;
      const matchesTime = timeFilter === "Any" || (timeFilter === "15 min or less" ? r.time <= 15 : timeFilter === "30 min or less" ? r.time <= 30 : r.time <= 60);
      const matchesDifficulty = difficultyFilter === "Any" || r.difficulty === difficultyFilter;
      const ingredientText = (r.ingredients || []).map(i => (i.n || "").toLowerCase()).join(" ");
      const meatWords = /chicken|beef|pork|turkey|bacon|ham|sausage|salmon|tuna|shrimp|fish|meat|anchovy|gelatin|lamb|steak|prosciutto/.test(ingredientText);
      const animalProductWords = /milk|cream|cheese|parmesan|feta|yogurt|butter|egg|honey|whey|mozzarella|ghee|mayonnaise|mayo/.test(ingredientText);
      const isVegetarian = !meatWords;
      const isVegan = !meatWords && !animalProductWords;
      const matchesDiet = dietFilter === "All" || (dietFilter === "Vegetarian" ? isVegetarian : isVegan);
      return matchesText && matchesCategory && matchesTime && matchesDifficulty && matchesDiet;
    });
    if (sortFilter === "Quickest") result.sort((a,b)=>a.time-b.time);
    if (sortFilter === "Newest") result.sort((a,b)=>{ const an=Number((a.id.match(/\d+/)||["0"])[0]); const bn=Number((b.id.match(/\d+/)||["0"])[0]); return bn-an; });
    return result;
  }, [recipes, search, category, timeFilter, difficultyFilter, dietFilter, sortFilter]);

  const suggestions = useMemo(() => recipes.filter(r => !favorites.includes(r.id)).slice(0,4), [recipes, favorites]);
  const selectedRecipe = recipes.find(r => r.id === selected);

  const openRecipe = (id) => {
    const recipe = recipes.find(r => r.id === id);
    if (!recipe) return;
    setPreviousView(view);
    setSelected(id);
    setServings(recipe.servings);
    setView("recipe");
  };

  const update = (key, value, setter) => { setter(value); save(key,value); };
  const toggleFavorite = id => {
    const next = favorites.includes(id) ? favorites.filter(x=>x!==id) : [...favorites,id];
    update("recipe-favorites", next, setFavorites);
  };
  const localRecipeCheck = (recipe, ingredients, steps) => {
    const clean = text => text.trim().replace(/\s+/g, " ");
    const title = clean(recipe.title || "");
    const description = clean(recipe.description || "");
    const ingredientNames = ingredients.map(i => clean(i.n).toLowerCase()).filter(Boolean);
    const stepText = steps.map(clean).filter(Boolean);
    const titleWords = title.toLowerCase().split(/\s+/).filter(Boolean);

    const foodWords = /chicken|beef|pork|turkey|bacon|ham|sausage|salmon|tuna|shrimp|fish|steak|pasta|noodle|rice|potato|bread|toast|sandwich|soup|salad|pizza|taco|burrito|curry|pancake|waffle|cake|cookie|brownie|muffin|oatmeal|egg|cheese|chocolate|apple|banana|berry|berries|tomato|bean|beans|lentil|vegetable|avocado|yogurt|smoothie|chili|stew|casserole|lasagna|burger|wrap|chicken|garlic|lemon/.test((title + " " + ingredientNames.join(" ")).toLowerCase());

    const nonsense = /^(asdf|qwerty|test|hello|blah|lorem|abc|123)+$/i.test(title.replace(/\s/g, ""));
    const hasQuantity = ingredients.some(i => Number(i.q) > 0);
    const hasAction = stepText.some(s => /add|mix|stir|cook|bake|boil|fry|heat|bowl|serve|chop|slice|blend|whisk|combine|season|place|pour|toast|grill|roast|preheat/i.test(s));

    const valid = title.length >= 3 &&
      ingredients.length >= 2 &&
      stepText.length >= 2 &&
      hasQuantity &&
      hasAction &&
      foodWords &&
      !nonsense;

    const polishedTitle = title
      .replace(/\s+/g, " ")
      .replace(/(^|[.!?]\s+)([a-z])/g, (_, p, ch) => p + ch.toUpperCase());

    return {
      valid,
      reason: valid ? "Recipe check passed." : "Please enter a real, coherent recipe with a food title, at least two ingredients, quantities, and at least two cooking steps.",
      title: polishedTitle,
      description,
      category: recipe.category,
      time: Number(recipe.time) || 30,
      difficulty: ["Easy","Medium","Hard"].includes(recipe.difficulty) ? recipe.difficulty : "Easy",
      servings: Number(recipe.servings) || 2,
      story: buildRecipeStory(polishedTitle, recipe.category),
      tags: titleWords.slice(0, 4),
      ingredients: ingredients.map(i => ({...i, n: clean(i.n)})),
      steps: stepText.map(s => s.charAt(0).toUpperCase() + s.slice(1).replace(/(?<![.!?])$/, "."))
    };
  };

  const buildRecipeStory = (title, category) => {
    const meal = category === "Breakfast" ? "morning" : category === "Lunch" ? "midday" : category === "Snacks" ? "snack break" : category === "Desserts" ? "dessert" : "dinner";
    return `This Flavorlyst recipe, ${title}, was made for a ${meal} when you want something delicious without overcomplicating the kitchen. It brings familiar ingredients together in a simple way that is easy to make, share, and remember.`;
  };

  const isAppropriateRecipeImageUrl = value => {
    if (!value) return true;
    try {
      const url = new URL(value);
      const allowedHost = /(^|\.)images\.unsplash\.com$/i.test(url.hostname);
      const blockedText = /porn|xxx|nsfw|nude|nudity|sex|violence|gore|blood|weapon|gun|drug|cocaine|marijuana|alcohol|beer|wine|casino|gambling/i.test(value);
      return url.protocol === "https:" && allowedHost && !blockedText;
    } catch {
      return false;
    }
  };

  const createRecipe = e => {
    e.preventDefault();
    if (aiStatus === "Checking recipe…") return;

    setAiStatus("Checking recipe…");

    const parsedIngredients = newRecipe.ingredients.split("\n").map(line => {
      const p = line.split("|");
      return { q: Number(p[0]) || 1, u: p[1]?.trim() || "", n: p[2]?.trim() || p[0]?.trim() || line.trim() };
    }).filter(i => i.n);

    const parsedSteps = newRecipe.steps.split("\n").map(s => s.trim()).filter(Boolean);
    const checked = localRecipeCheck(newRecipe, parsedIngredients, parsedSteps);

    if (!checked.valid) {
      setAiStatus("⚠️ " + checked.reason);
      return;
    }

    const suppliedImage = newRecipe.image.trim();
    if (suppliedImage && !isAppropriateRecipeImageUrl(suppliedImage)) {
      setAiStatus("⚠️ That photo URL isn't an accepted food-image source. Leave it blank and Flavorlyst will choose a food photo automatically.");
      return;
    }

    const selectedImage = suppliedImage || getAutomaticRecipeImage(checked.title, checked.ingredients);

    const recipe = {
      id:"u-"+Date.now(),
      title:checked.title,
      description:checked.description,
      category:checked.category,
      time:checked.time,
      difficulty:checked.difficulty,
      servings:checked.servings,
      author:"You",
      story:checked.story,
      image:selectedImage,
      tags:checked.tags,
      ingredients:checked.ingredients,
      steps:checked.steps
    };

    const next=[recipe,...recipes];
    update("recipe-recipes",next,setRecipes);
    setNewRecipe({title:"",description:"",category:"Dinner",time:30,difficulty:"Easy",servings:2,image:"",ingredients:"",steps:""});
    setAiStatus("");
    setPreviousView("add");
    setSelected(recipe.id);
    setServings(recipe.servings);
    setView("recipe");
  };

  const scaledIngredients = selectedRecipe?.ingredients.map(i => ({...i, q:i.q*(servings/selectedRecipe.servings)}));

  const hero = recipes[0] || starterRecipes[0];
  return (
    <div className={darkMode ? "app dark-mode" : "app"}>
      <header className="topbar">
        <button className="brand" onClick={()=>setView("home")}><span className="brand-mark">✦</span><span>Flavor<span className="brand-accent">lyst</span></span></button>
        <div className="desktop-search"><span aria-hidden="true">⌕</span><input aria-label="Search recipes and ingredients" value={search} onChange={e=>{setSearch(e.target.value);setView("explore")}} placeholder="Search recipes, ingredients..." /></div>
<button className="theme-btn" onClick={() => { const next = !darkMode; setDarkMode(next); save("flavorlyst-dark-mode", next); }} aria-label="Toggle dark mode">{darkMode ? "☀" : "☾"}</button><button className="install-btn" onClick={async ()=>{ if(installPrompt){ installPrompt.prompt(); await installPrompt.userChoice.catch(()=>{}); setInstallPrompt(null); } else { setShowInstall(true); } }}>Install App</button>
      </header>

      {view==="home" && <main className="home-page">
        <section className="hero" style={{backgroundImage:`linear-gradient(90deg,rgba(12,21,16,.9),rgba(12,21,16,.2)),url(${hero.image})`}}>
          <div className="hero-content"><span className="eyebrow">WELCOME TO FLAVORLYST</span><h1>Good food starts with a great idea.</h1><p>Discover recipes, save favorites, and plan your week.</p><div className="hero-actions"><button className="primary" onClick={()=>setView("explore")}>Explore recipes</button><button className="glass" onClick={()=>setView("add")}>＋ Add a recipe</button></div></div>
        </section>
        <section className="section"><div className="section-head"><div><span className="eyebrow dark">DISCOVER</span><h2>What are you craving?</h2></div><button className="text-btn" onClick={()=>setView("explore")}>See all →</button></div>
          <div className="chips">{categories.map(c=><button className={category===c?"chip active":"chip"} key={c} onClick={()=>{setCategory(c);setView("explore")}}>{c}</button>)}</div>
          <RecipeGrid recipes={filtered.slice(0,4)} onOpen={openRecipe} favorites={favorites} onFavorite={toggleFavorite}/>
        </section>
        <section className="section soft"><div className="section-head"><div><span className="eyebrow dark">PERSONALIZED</span><h2>Picked for you</h2></div></div><RecipeGrid recipes={suggestions} onOpen={openRecipe} favorites={favorites} onFavorite={toggleFavorite}/></section>
      </main>}

      {view==="explore" && <main className="page explore-page">
        <div className="explore-heading"><div><span className="eyebrow dark">EXPLORE</span><h1>Find something delicious</h1><p>Search by recipe, ingredient, or tag.</p></div><span className="result-count">{filtered.length} recipes</span></div>
        <div className="search-panel large-search"><span>⌕</span><input autoFocus value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search chicken, pasta, quick meals..."/><button className="filter-toggle" onClick={()=>setShowFilters(!showFilters)}>☷ Filters</button></div>
        <div className="chips category-row">{categories.map(c=><button className={category===c?"chip active":"chip"} key={c} onClick={()=>setCategory(c)}>{c}</button>)}</div>
        {showFilters && <div className="filter-panel">
          <label>Cooking time<select value={timeFilter} onChange={e=>setTimeFilter(e.target.value)}><option>Any</option><option>15 min or less</option><option>30 min or less</option><option>60 min or less</option></select></label>
          <label>Difficulty<select value={difficultyFilter} onChange={e=>setDifficultyFilter(e.target.value)}><option>Any</option><option>Easy</option><option>Medium</option><option>Hard</option></select></label>
          <label>Diet<select value={dietFilter} onChange={e=>setDietFilter(e.target.value)}><option>All</option><option>Vegetarian</option><option>Vegan</option></select></label>
          <label>Sort by<select value={sortFilter} onChange={e=>setSortFilter(e.target.value)}><option>Recommended</option><option>Quickest</option><option>Newest</option></select></label>
          <button className="clear-filters" onClick={()=>{setCategory("All");setTimeFilter("Any");setDifficultyFilter("Any");setDietFilter("All");setSortFilter("Recommended");setSearch("");}}>Clear all</button>
        </div>}
        <RecipeGrid recipes={filtered} onOpen={openRecipe} favorites={favorites} onFavorite={toggleFavorite}/>
      </main>}

      {view==="recipe" && selectedRecipe && <main className="recipe-page">
        <RecipeBackground className="recipe-cover" image={selectedRecipe.image} fallback={getAutomaticRecipeImage(selectedRecipe.title, selectedRecipe.ingredients || [])}><button className="back" onClick={()=>setView(previousView)}>← Back</button><div className="cover-bottom"><span className="pill">{selectedRecipe.category}</span><h1>{selectedRecipe.title}</h1><p>By {selectedRecipe.author}</p></div></RecipeBackground>
        <div className="recipe-layout"><div><section className="recipe-card story-card"><span className="eyebrow dark">THE STORY BEHIND IT</span><h2>A little history with your meal</h2><p>{selectedRecipe.story || `Every recipe has a story. This one was created by ${selectedRecipe.author || "a home cook"} and shared with the Flavorlyst community as a recipe worth passing along.`}</p></section><section className="recipe-card"><div className="card-head"><h2>Ingredients</h2></div><div className="servings"><span>Servings</span><button aria-label="Decrease servings" onClick={()=>setServings(Math.max(1,servings-1))}>−</button><b>{servings}</b><button aria-label="Increase servings" onClick={()=>setServings(servings+1)}>＋</button><small>Scaled automatically</small></div><ul className="ingredients">{scaledIngredients.map((i,idx)=><li key={idx}><b>{Number.isInteger(i.q)?i.q:i.q.toFixed(1)}</b><span>{i.u}</span><span>{i.n}</span></li>)}</ul></section><section className="recipe-card"><h2>How to make it</h2><div className="steps">{selectedRecipe.steps.map((s,i)=><div className="step" key={i}><span>{i+1}</span><p>{s}</p></div>)}</div></section></div></div>
      </main>}

      {view==="add" && <main className="page narrow"><div className="page-title"><span className="eyebrow dark">CREATE</span><h1>Add your recipe</h1><p>Share something delicious with the community.</p></div><form className="form-card" onSubmit={createRecipe}><label>Recipe title<input required value={newRecipe.title} onChange={e=>setNewRecipe({...newRecipe,title:e.target.value})} placeholder="e.g. Grandma's Sunday Lasagna"/></label><label>Recipe photo URL <small>Optional — leave blank and Flavorlyst will choose a food photo automatically.</small><input value={newRecipe.image} onChange={e=>setNewRecipe({...newRecipe,image:e.target.value})} placeholder="Optional: paste an Unsplash food-image URL"/></label><div className="two"><label>Category<select value={newRecipe.category} onChange={e=>setNewRecipe({...newRecipe,category:e.target.value})}><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snacks</option><option>Desserts</option></select></label><label>Difficulty<select value={newRecipe.difficulty} onChange={e=>setNewRecipe({...newRecipe,difficulty:e.target.value})}><option>Easy</option><option>Medium</option><option>Hard</option></select></label><label>Cooking time (minutes)<input type="number" min="1" max="600" value={newRecipe.time} onChange={e=>setNewRecipe({...newRecipe,time:e.target.value})}/></label><label>Servings<input type="number" min="1" value={newRecipe.servings} onChange={e=>setNewRecipe({...newRecipe,servings:e.target.value})}/></label></div><label>Description<textarea value={newRecipe.description} onChange={e=>setNewRecipe({...newRecipe,description:e.target.value})} placeholder="What makes this recipe special?"/></label><label>Ingredients <small>One per line: quantity | unit | ingredient</small><textarea required value={newRecipe.ingredients} onChange={e=>setNewRecipe({...newRecipe,ingredients:e.target.value})} placeholder={"2 | cups | flour\n1 | tsp | salt\n3 | | eggs"}/></label><label>Steps <small>One step per line</small><textarea required value={newRecipe.steps} onChange={e=>setNewRecipe({...newRecipe,steps:e.target.value})} placeholder={"Mix the ingredients.\nBake until golden.\nServe warm."}/></label><button className="primary big" type="submit" disabled={aiStatus==="Checking recipe…"}>{aiStatus==="Checking recipe…" ? "Checking recipe…" : "✓ Check recipe & publish"}</button>{aiStatus && <p className="ai-status">{aiStatus}</p>}</form></main>}

      {view==="planner" && <main className="page"><div className="page-title"><span className="eyebrow dark">PLAN AHEAD</span><h1>Weekly meal planner</h1><p>Build your week with your favorite recipes.</p></div><div className="planner">{Object.entries(planner).map(([day,id])=><div className="day" key={day}><b>{day}</b>{id ? <RecipeBackground className="planned" image={recipes.find(r=>r.id===id)?.image} fallback={getAutomaticRecipeImage(recipes.find(r=>r.id===id)?.title || "", recipes.find(r=>r.id===id)?.ingredients || [])}><span>{recipes.find(r=>r.id===id)?.title}</span><button aria-label={`Remove ${recipes.find(r=>r.id===id)?.title || "recipe"} from ${day}`} onClick={()=>{const next={...planner,[day]:null};update("recipe-planner",next,setPlanner)}}>×</button></RecipeBackground> : <select value="" onChange={e=>{const next={...planner,[day]:e.target.value};update("recipe-planner",next,setPlanner)}}><option value="">＋ Add recipe</option>{recipes.map(r=><option key={r.id} value={r.id}>{r.title}</option>)}</select>}</div>)}</div></main>}

      {view==="saved" && <main className="page"><div className="page-title"><span className="eyebrow dark">YOUR COLLECTION</span><h1>Saved recipes</h1><p>Your favorites, all in one place.</p></div><RecipeGrid recipes={recipes.filter(r=>favorites.includes(r.id))} onOpen={openRecipe} favorites={favorites} onFavorite={toggleFavorite}/></main>}

      {showInstall && <div className="modal-wrap" onClick={()=>setShowInstall(false)}><div className="modal" onClick={e=>e.stopPropagation()}><button className="modal-x" aria-label="Close install instructions" onClick={()=>setShowInstall(false)}>×</button><div className="install-icon">✦</div><h2>Install Flavorlyst</h2><p>{installPrompt ? "Flavorlyst can be installed as an app on this device." : <>Use your browser's <b>Add to Home Screen</b> option to keep your recipe app handy. On supported browsers, use the install button in the address bar.</>}</p>{installPrompt ? <button className="primary full" onClick={async ()=>{ const prompt=installPrompt; setShowInstall(false); prompt.prompt(); await prompt.userChoice.catch(()=>{}); setInstallPrompt(null); }}>Install Flavorlyst</button> : <button className="primary full" onClick={()=>setShowInstall(false)}>Got it</button>}</div></div>}


      <nav className="bottom-nav"><Nav icon="⌂" label="Home" active={view==="home"} onClick={()=>setView("home")}/><Nav icon="⌕" label="Explore" active={view==="explore"} onClick={()=>setView("explore")}/><button className="add-nav" onClick={()=>setView("add")}>＋</button><Nav icon="▣" label="Planner" active={view==="planner"} onClick={()=>setView("planner")}/><Nav icon="♡" label="Saved" active={view==="saved"} onClick={()=>setView("saved")}/></nav>
    </div>
  );
}

function Nav({icon,label,active,onClick}) { return <button className={active?"nav-item active":"nav-item"} onClick={onClick}><span>{icon}</span><small>{label}</small></button>; }

function RecipeBackground({image, fallback, className, gradient, children}) {
  const [src, setSrc] = useState(image || fallback);
  useEffect(() => {
    setSrc(image || fallback);
  }, [image, fallback]);
  return (
    <div className={className} style={{backgroundImage:`${gradient || "linear-gradient(0deg,rgba(8,12,10,.78),rgba(8,12,10,.05))"},url("${src}")`}}>
      <img src={image || fallback} alt="" aria-hidden="true" style={{display:"none"}} onError={() => setSrc(fallback)} />
      {children}
    </div>
  );
}

function RecipeGrid({recipes,onOpen,favorites,onFavorite}) {
  if (!recipes.length) return <div className="empty">No recipes found yet.</div>;
  return <div className="recipe-grid">{recipes.map(r=><article className="recipe-card-tile" key={r.id}>
    <button className="tile-image" onClick={()=>onOpen(r.id)}>
      <img src={r.image || getAutomaticRecipeImage(r.title, r.ingredients || [])} alt={r.title} loading="lazy"
        onError={e=>{
          const fallback=getAutomaticRecipeImage(r.title,r.ingredients||[]);
          if(e.currentTarget.dataset.fallback!=="1" && e.currentTarget.src!==fallback){
            e.currentTarget.dataset.fallback="1";
            e.currentTarget.src=fallback;
          } else {
            e.currentTarget.style.display="none";
            e.currentTarget.parentElement.classList.add("image-fallback");
          }
        }} />
      <span className="tile-image-shade" />
      <span className="tile-time">{r.time} min</span>
      <span className="tile-title">{r.title}</span>
    </button>
    <div className="tile-meta"><div><span>{r.difficulty}</span></div><button onClick={()=>onFavorite(r.id)} className="heart" aria-label={favorites.includes(r.id) ? `Remove ${r.title} from saved recipes` : `Save ${r.title}`}>{favorites.includes(r.id)?"♥":"♡"}</button></div>
  </article>)}</div>;
}

export default App;